"""СВЕДЕНИЕ — вокал и бит в черновой трек: бот сводит две дорожки за пару минут.

Зачем. Артисту без денег свести трек негде: инженер берёт 3–10 тысяч, самому
учиться годами. Две дорожки, выгруженные с одного начала, — вокал и бит — бот
сводит в трек, который не стыдно выложить, и он же идёт в канал прямо из-под
готового трека — кнопкой «🎙», без площадок (otbor.mixed).
Обещание честное: черновое сведение автоматом, не работа звукорежиссёра, — «как
на студии» не обещаем. До 27.09.2026 функция звалась СКЛЕЙКОЙ, но люди читали её
как «бот просто склеит дорожки», а не сведёт их. Имя СВЕДЕНИЕ до 22.09.2026 носили
проценты совпадения — теперь это ДВОЙНИК (src/svedenie.py, имя файла историческое).
Имя модуля и метки ?start=skleyka_* остались прежними: старые
ссылки уже разосланы по чатам. Команда с 28.09.2026 — /svedenie: /skleyka в меню
«/» выдавала старое имя; прежняя понимается при наборе.

Как. Только ffmpeg: он уже стоит в дежурстве, а считать хватает машины Actions.
Громкость дорожек на входе любая — телефон, студия, бит с YouTube, — поэтому
каждый уровень выставляется по замеру EBU R128, а не коэффициентом:

1. Вокал приводится к VOCAL_LUFS, и только потом компрессия VOCAL_CHAIN — её пороги
   отсчитаны от этого уровня. Иначе тихая запись прошла бы мимо компрессора,
   а громкая сплющилась. Вторая ступень — не больше, чем нужно до плотности
   голоса релизов (VOCAL_SWING): уже сведённый голос второй раз не сжимается.
   Голос, записанный в один канал стерео, встаёт в центр.
2. Тембр вокала подтягивается в пределы сведённого рэп-вокала (TONE) по замеру октав —
   на весь трек и по ходу трека: домашние записи расходятся на 10 дБ, а куски
   одной записи — на 6–7, и одна полка на всех не годится. Гул записи вплотную
   к микрофону, 125–500 Гц, снимается глубже остального (TONE_BODY).
3. Бит: перевёрнутый канал (низ в противофазе) возвращается; место голосу — как soothe с голосом
   в сайдчейне: середина бита приседает по полосам выше 120 Гц ключом от тех же
   полос голоса, глубже всего в 1–4 кГц и только пока голос звучит (ROOM_*) —
   и только в полосах, где голос стоит над битом ниже, чем в рядовом релизе.
   Низ и края не тронуты: бочка и 808 качают, бит остаётся широким.
4. Баланс — как у релизов по EBU R128 (голос на 2 дБ тише бита), а у дорожек
   из одного проекта — как у артиста (SAME_PROJECT); по ходу трека голос ведёт
   райдер: где бит его перекрывает глубже, чем бывает в релизах, голос плавно
   поднимается. Один баланс на весь трек владелец услышал с первой
   прослушки: «где-то будто слишком громкий бит».
5. Стиль (STYLES) — набор эффектов, названный словом, понятным без знания
   сведения. Отзвук, дилей и дабл — шинами, доля к сухому голосу по замеру,
   как в reels.studio.
6. Саунд-дизайн — по флагу, сдержанный: вдох перевёрнутого отзвука перед первым
   словом, бит из-под фильтра до первого слова (если у бита рядом нет своего дропа),
   телефон на строках перед первым дропом, два броска дилея на концах фраз,
   остановка плёнки в конце. Всё на удар бочки, синтезом ffmpeg, громкость — к голосу.
7. Мастер — низ ниже 120 Гц в моно, склейка шины 2:1, жёсткий клиппер по верхушкам
   ударов и ограничитель до MASTER_LUFS, пик не выше CEILING dBTP — и у WAV,
   и у MP3, которым трек уходит человеку.

Ручки бота — mix(..., voice=, echo=): голос к биту и доля эха, в дБ. Дорожки
по отдельности — mix(..., parts=): даблы за ведущим его же райдером, бэки шире
и дальше в отзвук, эдлибы — каждый выкрик в свою точку панорамы, к одной громкости и в эхо (PARTS), и так же
бэк, который на деле — короткие выкрики между строк (BACK_SHOUT); место голосу — только в музыке,
удары бочки — по барабанам и басу. Простой режим — две дорожки.

Промежуточное — во float: пики выше нуля между шагами не срезаются, режет только
мастер. Подгонку под референс (Matchering) сюда не тащим: это
новый пакет и обещание «как у звезды», которое черновое сведение не сдержит.

Проверка — на слух: ДО (простая сумма дорожек) и ПОСЛЕ одной громкости по LUFS.
Громкое всегда кажется лучше, и без этого сравнение нечестное.

Слушать каждый трек некому, поэтому перед отправкой — контроль (control): то, что ухо ловит
на первой секунде, а замеры громкости и тембра не видят. Пустое начало, хвост после конца
бита и пик выше потолка бот чинит и говорит об этом строкой в подписи; пропавший голос, голос
мимо бита и тишину внутри трека не починить — трек уходит всё равно, владельцу строка в личку.
Отказ вместо трека отвергнут: человек ждал, и трек с изъяном ему полезнее, чем «не вышло».
Провал короче — бит замолк перед входом следующей части, а голос ещё молчит — закрывает само
сведение: эхо последнего слова держится до входа (_hold), человеку — тоже строка в подписи.

Выход из лимита суток — только тому, кто в него упёрся: две кнопки под отказом,
бесплатная функция остаётся бесплатной. «Позвать артиста» — личная ссылка
?start=skleyka_r<код>, и трек сверх лимита даётся за первый готовый трек
приглашённого, а не за переход: переход второй аккаунт накрутит за минуту, готовый трек —
это подписка на канал и настоящие дорожки. «Больше треков» — счёт в звёздах Telegram:
цифровой товар Telegram пускает только за звёзды (XTR), и платёжный провайдер для них
не нужен — ни договора, ни ключа, provider_token пустой; возврат по просьбе покупателя —
правило Telegram, поэтому /vozvrat владельца, а /paysupport покупателя (его Telegram
тоже требует) — тот же /vopros: вопрос владельцу вместе с номерами платежей, и ответ
владельца ответом на него бот пересылает человеку сам. За звёзды — только число треков.
Коды, бонусы и номера платежей — в SKLEYKA_FILE, приватном хранилище.

Ручное сведение («🎧 Отдать звукорежиссёру», до 05.10.2026 — «🎧 Свести руками») бот продаёт сам: задаток → кусок → перевод → целый трек. Файлы
звукорежиссёр шлёт с Мака ботом владельцу в личку (--hand), а клиенту их копирует дежурство по кнопке
владельца — состояние пишет только оно, запись с Мака дежурство затёрло бы своей. Задаток — звёздами
и до начала работы (владелец, 05.10.2026): заказ стоил человеку одного нажатия, он получал готовый кусок
и пропадал. Счёт тот же, что у «Больше треков», заявка уходит владельцу только после оплаты, возврат —
его кнопкой «↩️ Не беру»: она же метит трек, и новый счёт по нему не выставляется, а внесённый задаток
второй раз не принять (checkout). Заказ идёт только из-под готового трека: без него звукорежиссёру нечего
слушать, а ник в ответе уводил человека в личку мимо задатка. Целиком за звёзды цена отвергнута: остальное — перевод человеку, приход денег
подтверждает владелец кнопкой, бот банка не видит. Под предложением — «🎧 Примеры: до и после»: по каждой работе два куска
одного места и одной громкости, ДО свёл бот, ПОСЛЕ — звукорежиссёр. Отзывов и регалий нет по-прежнему — человек слушает сам.
Каталог (config.SKLEYKA_HAND_EXAMPLES, пары file_id) пишет Мак (--example), дежурство его только читает; пуст — кнопки нет.
После пар — вкладыш альбома самого звукорежиссёра (config.SKLEYKA_HAND_ALBUM, записан готовым, площадки по нажатию не спрашиваются).

    python -m src.skleyka --mix ВОКАЛ БИТ --out ПАПКА   сведение, пара ДО/ПОСЛЕ одной громкости и ролик
    python -m src.skleyka --mix ВОКАЛ БИТ --out ПАПКА --style грязно --design
    python -m src.skleyka --mix ВОКАЛ БИТ --out ПАПКА --voice 2 --echo -4   ручки «голос громче», «эха меньше»
    python -m src.skleyka --mix ВОКАЛ БИТ --out ПАПКА --part бэк БЭКИ --part барабаны БАРАБАНЫ   по дорожкам
    python -m src.skleyka --mix ВОКАЛ БИТ --out ПАПКА --like ТРЕК   тембр, ширина и громкость — к чужому треку
    python -m src.skleyka --mix ВОКАЛ БИТ --out ПАПКА --old СТАРЫЙ   голос с чужого бита — на БИТ, темп до ±8 %
    python -m src.skleyka --beats Kizaru --bpm 142   бесплатные биты в темпе голоса, без Telegram
    python -m src.skleyka --hand 026a4b --price 1500 --piece КУСОК ДО-ПОСЛЕ --full WAV MP3 --text ТЕКСТ
                                                     ручное сведение владельцу в личку, дальше — кнопками (только Мак)
    python -m src.skleyka --deposit 026a4b [--dry-run]   заявке без задатка — условия и счёт задатка человеку (только Мак)
    python -m src.skleyka --example ДО ПОСЛЕ [--dry-run]   пара примера ручного сведения — владельцу в личку и в каталог (только Мак)
"""

from __future__ import annotations

import argparse
import array
import concurrent.futures
import contextlib
import hashlib
import hmac
import html
import itertools
import json
import math
import re
import secrets
import shutil
import statistics
import subprocess
import sys
import tempfile
import urllib.parse
import urllib.request
import wave
import zipfile
from datetime import datetime, timedelta, timezone
from pathlib import Path, PurePosixPath

from . import clips, config, llm, oblako, reels, state, telegram
from .sources import itunes, youtube_comments

RATE = 44100
# Любой формат на входе: моно становится стерео, частота — 44,1 кГц. Неслышимое
# срезается сразу: замер громкости его считает, а MP3 выбрасывает. В бите
# Little Chicago's Finest ультразвук над 20 кГц завышал громкость на 5 LU —
# вокал встал бы под мусор, а MP3 вышел бы на 5 дБ тише замера.
FORMAT = f"aformat=sample_fmts=flt:sample_rates={RATE}:channel_layouts=stereo,highpass=f=20,lowpass=f=20000"
MP3 = ["-c:a", "libmp3lame", "-b:a", "320k"]
# Середина и бока (M/S): середина — в левом канале, бока — в правом. Фильтр
# с c=FL между MS и LR трогает только середину, с c=FR — только бока.
MS = "pan=stereo|c0=0.5*c0+0.5*c1|c1=0.5*c0-0.5*c1"
LR = "pan=stereo|c0=c0+c1|c1=c0-c1"

# --- вокал ------------------------------------------------------------------
# Низ ниже 90 Гц — гул и хлопки на «п» и «б».
HIGHPASS = "highpass=f=90"
VOCAL_LUFS = -18.0
# Микрофон во входе 1 звуковой карты пишет стереодорожку с голосом в одном
# канале: каналы расходятся больше чем на LOPSIDED дБ — громкий идёт в оба.
LOPSIDED = 6.0
# Компрессия плотнее дикторской (reels.VOICE_CHAIN, ratio 3 почти вхолостую):
# быстрый ловит пики (порог −16 дБ), второй ровняет строку (−26 дБ, ratio 3).
# При VOCAL_LUFS голос в строке идёт около −20 дБ, и второй давит 3–4 дБ постоянно.
# Второй — по замеру: подмешивается параллельно той долей из LEVEL_STEPS, при которой
# размах голоса внутри строк (swing) не мельче VOCAL_SWING — медианы 420 голосов
# релизов, разделённых demucs (квартили 20,2…27,7 дБ). Экзамен на 40 релизах
# 28.09.2026 (src/ekzamen.py): уже сведённый голос обе ступени целиком сжимали ещё
# на 4,6 дБ размаха (квартили −6,1…−3,7) — тихое между слогами, вдохи и шум
# поднимались к слову; с долей по замеру — на 2,0, почти одна первая ступень (1,6).
# Сырой голос владельца («Асапчик», размах 27,6 и 29,1 дБ) выходит на 24,5 и 24,0 —
# медиана релизов, — а не на 22,2 и 22,7, как с обеими ступенями целиком.
VOCAL_CHAIN = (
    "acompressor=threshold=0.158:ratio=4:attack=1:release=60",
    "acompressor=threshold=0.05:ratio=3:attack=10:release=150:knee=4",
)
VOCAL_SWING = 23.9
# Первая ступень — тоже долей по замеру: пик голоса к его громкости (PLR, после среза
# HIGHPASS) не ниже VOCAL_PLR — медианы тех же 420 голосов (квартили 11,8…13,9 дБ).
# Сырому голосу она нужна — у «Асапчика» PLR 15,9, — а уже сведённый целиком давила
# на 1,3 дБ пика и 1,6 дБ размаха сверх релиза. Экзамен 28.09.2026 с долей по замеру:
# уже сведённый голос к релизу — пик −0,1 дБ вместо −1,3, размах −1,4 вместо −2,4
# (после компрессии −0,5 вместо −2,0), атака −0,2 вместо −0,5; баланс не сдвинулся.
# Голос «Асапчика» — первая ступень на 75%, PLR 12,5 и 12,8.
VOCAL_PLR = 12.7
LEVEL_STEPS = (1.0, 0.75, 0.5, 0.25, 0.0)
# Сжатый голос — на SQUEEZED_LUFS, сколько бы ни сжала вторая ступень: де-эссер,
# перегруз DIRT и третья ступень DENSE зависят от громкости входа и настроены на ту,
# с которой голос выходил из обеих ступеней целиком (медиана 40 релизов −24,8 LUFS).
# Без этого голос, сжатый слабее, приходил к де-эссеру на 5 дБ громче, и тот резал
# 8 кГц у уже сведённого голоса на 3,7 дБ вместо 2,3 (экзамен 28.09.2026: тембр
# голоса в 8 кГц −2,8 дБ к релизу против −0,5 до правки; на −25 — −0,7).
SQUEEZED_LUFS = -25.0
# Тембр — после компрессии и по замеру, а не одной полкой на всех: домашние
# записи расходятся на 10 дБ. У конденсатора вплотную середина бубнит (у Little
# Chicago's Finest полоса 250 Гц на 5 дБ выше 1 кГц), у телефона её нет вовсе,
# а компрессия поднимает тихое — и гул, и шипящие. Цель — октавы голоса к 1 кГц
# в пределах квартилей 420 релизов с голосом, разделённых demucs (медианы: 125 Гц −9,
# 250 Гц 0, 500 Гц +2, 2 кГц −2,5, 4 кГц −6, 8 кГц −7): голос внутри них не трогается,
# за краем — подтягивается к краю. До 28.09.2026 цель была медианой, и экзамен
# на 40 релизах показал, что голос из ряда релизов уводится от своего же релиза
# дальше порчи: среднее отклонение тембра 1,5 дБ против 1,2 у испорченного; с краями —
# 1,3 (квартили 1,0…1,8), остаток — в 8 кГц от DEESSER и в 125 Гц. Ещё раньше
# целью был один тёмный голос (Grants — PunchDrunk из MedleyDB), на 6 дБ тоньше
# релизов в 250 Гц: подгонка к нему резала тело и верх, оставляя 1–2 кГц, — владелец:
# «голос как из телефонной трубки, крепость ушла». Вниз — не больше 4 дБ: к этой цели
# гудящему конденсатору (250 Гц на 5 дБ выше 1 кГц) хватает, а глубже режется уже
# чей-то замысел (тело голоса — глубже, TONE_BODY ниже). Вверх — только разборчивость, 2–4 кГц, и не больше 3 дБ: поднятый
# низ гудит, поднятый верх шипит. Дорожки из одного проекта не подгоняются вовсе
# (SAME_PROJECT): тембр там выставил артист — решение владельца от 28.09.2026, хотя
# у его «Асапчика» после цепочки 125 Гц на 18 дБ выше медианы релизов, а 8 кГц — на 6.
TONE = {125: (-15.4, -3.0), 250: (-3.5, 2.9), 500: (-0.1, 4.1), 2000: (-4.2, -0.8), 4000: (-8.7, -3.0), 8000: (-9.7, -3.3)}
TONE_CUT = -4.0
# В октавах тела, 125–500 Гц, вниз можно глубже. 01.10.2026 владелец о своём «Отрывайся»:
# «звучит как демка»; бит по замеру оказался в ряду релизов, а голос — нет: запись
# конденсатором вплотную после компрессии держала 250 и 500 Гц на 9,1 и 9,7 дБ выше 1 кГц,
# на 6 дБ за краем TONE, и три колокола по −4 сняли только 3,1 и 2,4 — соседние задевают
# и сам 1 кГц, к которому меряется тембр. В готовом треке голос в 500 Гц вышел гуще, чем
# у всех 40 релизов экзамена (+7,7 при крае +4,1). С −8 те же колокола дают +2,4 и +4,3 —
# к краям. Тоньше релизов голос от этого не станет: цель — верхний край, а не медиана.
# Глубже — только когда 2 и 4 кГц (TONE_PRESENCE) в своих пределах: тембр меряется к 1 кГц,
# и если за верхним краем и тело, и верх, провален сам 1 кГц, а не гудит тело. Без этой
# оговорки экзамен на 12 релизах уводил один голос (низ и верх разом за краями) от своего
# релиза ещё на 2 дБ в 125 и 250 Гц; с ней экзамен тот же, что до правки.
TONE_BODY = {125: -8.0, 250: -8.0, 500: -8.0}
TONE_PRESENCE = (2000, 4000)
TONE_BOOST = {2000: 3.0, 4000: 3.0}
# Тембр по ходу трека: куски одной записи пишутся по-разному — у Little Chicago's
# Finest на 176–192 с полоса 500 Гц на 5 дБ выше 1 кГц, на 160–168 — на 5 ниже,
# и одна поправка на весь трек оставляла на 2:58 «коробку» (владелец: «плотность
# пропала, начал звучать дёшево»). Поэтому к общей поправке — своя по окнам
# TONE_STEP с: октавы к 1 кГц, сглаженные на TONE_SPAN с по окнам с голосом,
# тянутся к среднему тембру уже поправленного голоса. Это и есть TONE там, где
# общая поправка его достала, а где упёрлась в предел — окна не тащат за предел
# весь трек. Не дальше TONE_LOCAL дБ от общей, вверх — не выше TONE_BOOST.
# Замер: на 176–192 с стало +2,8, на 160–168 — −2,3 (дальше не пускает TONE_LOCAL);
# куски по 3 с на пяти треках отходят от среднего тембра на 1,1–1,4 дБ вместо 2,4–3,0.
TONE_STEP = 0.5
TONE_SPAN = 3.0
TONE_LOCAL = 4.0
# Де-эссер последним: подъём разборчивости и компрессия сами добавляют свиста.
# Сила — по замеру, как у первой ступени компрессии: самая большая из DEESS_STEPS,
# при которой шипящие к голосу (hiss) не тише VOCAL_HISS — медианы тех же 420 голосов
# релизов после _squeeze (квартили −12,1…−7,4 дБ; до компрессии медиана −10,7 —
# компрессия и правда поднимает свист). Одна сила на всех не годится: у ffmpeg она
# почти порог и срабатывает по уровню, а не по тому, сырой голос или сведённый.
# 0,5 у 20 голосов релизов резала шипящие на 2,7 дБ, а 8 кГц целиком — на 1,6
# (медианы), и экзамен 28.09.2026 показал голос в 8 кГц на 1,1 дБ темнее своего
# релиза; 0,4 голос релиза почти не трогает (8 кГц −0,3), но и шипящие сырого
# «Асапчика» режет лишь на 0,7–0,9 дБ. По замеру у «Асапчика» (голос, лид, дабл)
# шипящие до компрессии −7,1…−7,6 дБ, после −5,8…−6,9; выбрана сила 0,45 —
# −7,9…−8,7, срез 1,8–2,3 дБ (0,5 резала на 3,7–4,6, ниже релизов). Из 20 голосов
# релизов 12 идут без де-эссера, 8 кГц у них — медиана 0 вместо −1,6. Экзамен
# на 40 релизах: голос в 8 кГц к своему релизу −1,14 → 0,00 (квартили −0,4…+0,4),
# среднее отклонение тембра 0,40 → 0,27; у испорченного голоса 8 кГц −1,15 → −0,50.
# Бэк и эдлибы — прежним DEESSER без замера: они фоном, тише ведущего.
DEESSER = "deesser=i=0.5"
DEESS_STEPS = (0.5, 0.45, 0.4)
VOCAL_HISS = -9.6

# --- бит --------------------------------------------------------------------
# Место голосу — как soothe с голосом в сайдчейне (руководство soothe2: «carve out
# space for the vocals by using them as the sidechain key input… with the mid/side
# stereo mode»; Jaycen Joshua ставит подавитель резонансов на шину музыки с голосом
# в ключе, Podlesny Twins — Soothe на мелодии «на частоты вокала»): середина бита
# (M/S) по полосам выше 120 Гц приседает компрессорами с ключом от тех же полос
# голоса — только там и тогда, где голос звучит. Ниже 120 Гц голоса нет (срез
# HIGHPASS), и бочка с 808 не трогаются вовсе; края бита тоже. Полосы — крутые
# фильтры по SPLIT, 24 дБ на октаву: полоса 120–250 Гц ниже 120 почти не задевает.
SPLIT = (120, 250, 500, 1000, 2000, 4000, 8000)
# Глубина полосы — недостача места: на сколько голос в полосе стоит над битом ниже,
# чем в рядовом релизе (ROOM_GAP), по медиане окон 0,1 с с голосом при балансе
# сведения — мерка экзамена (ekzamen.pocket). ROOM_GAP — медиана 405 релизов,
# разделённых demucs (выборка экзамена в них не входит). До 09.10.2026 глубиной была
# маскировка в десятой части окон, где бит перекрывает голос сильнее всего, но там бит
# громче голоса и у релизов: в 1–2 кГц на 11,5 дБ по медиане (квартили +6,5…+17,2) —
# это слоги, где голоса в полосе почти нет. Глубина упиралась в потолок у 28–39 сведений
# экзамена из 40 в каждой полосе: замер ничего не решал, и место делалось там, где оно
# уже сделано, — голос над битом выходил выше своего релиза на 2,7 / 3,8 / 4,7 дБ
# в 500–1000 / 1000–2000 / 2000–4000 Гц (экзамен 09.10.2026, «не испорти готовое»;
# из сырого — 2,8 / 4,8 / 5,9), а на двух ручных заказах бит в 1–4 кГц приседал
# под голосом на 2,1 и 4,2 дБ при 1,1 и 2,5 у ручного сведения. С недостачей голос
# выше своего релиза на 1,6 / 2,1 / 2,5 дБ (из сырого — 1,7 / 2,8 / 3,3), на заказах бит
# приседает на 0,3 и 2,2 дБ, сам бит после места тише на 0,3 LU вместо 0,6. Остаток —
# место у той половины сведений, где голос стоит ниже рядового релиза (так и задумано),
# и 0,3–0,4 дБ от прочих шагов: столько расчёт по тем же сведениям давал вовсе без места.
# Потолок ROOM_CAP: больше всего в 1–4 кГц, где разборчивость, — 5 дБ, столько у релизов
# от нижнего квартиля до медианы (4,9 и 5,4 дБ): голос из плотного релиза дотягивается
# до рядового, не дальше; мало в 120–250 Гц — это тело бита — и выше 8 кГц. Отпуск длиннее на низких
# полосах: быстрый на 120 Гц качал бы саму волну. Ratio 1,25 и порог на 5 глубин
# ниже обычного слога: провал почти один на громком и на тихом слоге, как у soothe,
# который режет, пока в ключе есть голос, и как у Сениора (1,04:1, не больше 2 дБ).
# С ratio 2 тихие слоги — а бит перекрывает именно их — получали вдвое меньше
# громких: у Little Chicago's Finest в 1–2 кГц 1,8 дБ против 4,0 на медиане.
# Замер на трёх треках против прежнего провала 2,8 кГц и сайдчейна на весь бит:
# голос к биту в 1–2 кГц по медиане +8,7 / +7,6 / +4,8 дБ вместо +5,8 / +5,6 / +2,6
# (Little Chicago's Finest, M.E.R.C. Music, projectquestion), в 2–4 кГц +10,1 / +8,9 /
# +9,8 вместо +8,4 / +7,0 / +7,8; бит громче голоса по EBU R128 в 13 / 11 / 14% окон
# с голосом вместо 11 / 12 / 13%: низ больше не приседает, и общую громкость
# место почти не трогает — её ведёт райдер.
ROOM_CAP = (1.5, 2.0, 3.0, 5.0, 5.0, 3.0, 1.5)
ROOM_GAP = (-7.8, 1.3, 4.1, 5.0, 5.0, 2.5, 2.8)
ROOM_RELEASE = (250, 200, 150, 100, 80, 60, 50)
ROOM_RATIO = 1.25
ROOM_PAD = "apad=pad_dur=5"  # с запасом: входы сайдчейна расходились к концу на 0,2 с

# --- баланс -----------------------------------------------------------------
# Вокал к биту по EBU R128. Бит без пауз, а у вокала паузы отсекает сам замер,
# так что 0 — голос в строке вровень с битом. −2 — медиана релизов (у 447 треков,
# разделённых demucs, −1,9 дБ). До 28.09.2026 стоял 0, и вместе с райдером голос
# выходил на 3,2 дБ громче, чем в своём же релизе (экзамен на 40 релизах, квартили
# +0,6…+4,7): «голос не лежит в бите». С −2 и RIDE_TARGET — +0,1 (−2,3…+1,3).
VOCAL_OVER_BEAT = -2.0
# Голос и бит одной длины (расходятся не больше SAME_PROJECT с) выгружены из одного
# проекта — так просит FROM_START, — и баланс между ними поставил артист: он и остаётся,
# как и тембр голоса (TONE).
# 28.09.2026 у «Асапчика» владельца голос был на 6,8 дБ тише бита, вровень с райдером
# вышло на 1,8 громче — «голос не лежит в бите, пластиковый и воздушный»: поверх бита
# слышна вся обработка; с его балансом — «лежит лучше». Пределы BALANCE_RANGE — как
# в релизах: у 447 треков, разделённых demucs, голос к музыке по медиане −1,9 дБ,
# у девяти из десяти с голосом — от −9 до +3. Тише −9 — скорее забытая громкость
# дорожки, чем замысел.
SAME_PROJECT = 2.0
BALANCE_RANGE = (-9.0, 3.0)
# Райдер — как звукорежиссёр с фейдером голоса: громкость голоса окнами 0,4 с
# (EBU R128 M) против бита в те же окна. Где голос отстаёт от своего баланса больше
# чем на RIDE_TARGET, он поднимается до RIDE_MAX дБ (у Waves Vocal Rider по умолчанию
# те же ±6); подъём держится RIDE_HOLD и сглажен на RIDE_SMOOTH, чтобы голос
# не прыгал по слогам, а в паузах голоса возвращается к нулю — иначе поднятыми
# остались бы вдохи и шум. Вниз не ведём: громкие места ровняют компрессоры.
# С одним балансом на весь трек бит перекрывал голос больше чем на 2 дБ в 21–23%
# окон на трёх рэп-треках учебной библиотеки, с райдером — в 3–5%. Простое
# среднее без удержания сглаживало подъём на провале и оставляло 9–13%.
# Но и у релизов бит перекрывает голос больше чем на 2 дБ в трети окон (медиана
# 40 релизов 33%, квартили 12…61%), а в десятой части окон голос на 3,9 дБ тише
# своего баланса (квартили −4,7…−3,2). До 28.09.2026 райдер тянул каждое окно
# к самому балансу, и голос выходил громче, чем его свёл артист: на 1,3 дБ у дорожек
# из проекта, с перекрытием в 10% окон против 33% у релиза. RIDE_TARGET −4 — только
# провалы глубже, чем бывают в релизах: у дорожек из проекта голос громче релиза
# на 0,3 дБ, перекрытых окон на 5 меньше, чем у релиза, а не на 19.
RIDE_TARGET = -4.0
RIDE_MAX = 6.0
RIDE_HOLD = 0.5
RIDE_SMOOTH = 1.0
# Голос звучит в окне, если оно громче общей громкости голоса минус RIDE_GATE LU.
RIDE_GATE = 10.0

# --- стили ------------------------------------------------------------------
# «Грязно»: полоса 300 Гц – 4,5 кГц и перегруз мягким клиппером на +9 дБ.
# Клиппер считает на учетверённой частоте: гармоники выше 22 кГц иначе
# завернулись бы обратно в слышимое свистом.
DIRT = "highpass=f=300,lowpass=f=4500,volume=9dB,asoftclip=type=atan:oversample=4,volume=-9dB"
# «Близко»: третья ступень компрессии, голос ровный, как у самого микрофона.
DENSE = "acompressor=threshold=0.03:ratio=6:attack=3:release=60:knee=4"
# Дабл моно-голосу — по Сениору (Sound On Sound): копии в разные края со сдвигом
# 11 и 13 мс, высота гуляет на ±5 центов (vibrato: глубина 0,5 на 0,4 Гц — замер
# ±5,4 цента), на 15 дБ тише голоса. Второго дубля у артиста нет, и дабл из той же
# записи — старый студийный приём (ADT); без расстройки копия слилась бы
# с голосом гребёнкой.
# vibrato в ffmpeg (6.1–8.0) первые 5 мс читает свою линию задержки раньше, чем пишет:
# буфер не обнулён, и на Linux там лежит чужая память — числа вроде 1e214, во float это inf.
# Одна бесконечность в начале бэка, и фильтры мастера делают NaN из всего трека
# (сбой 29–30.09: склейка шины мерила −70 LUFS). Поэтому задержка на 6 мс длиннее,
# а первые 6 мс — вон: сдвиг прежний с точностью до отсчёта, мусора нет.
DOUBLE = (
    "[0:a]highpass=f=150,pan=mono|c0=0.5*c0+0.5*c1,asplit[a][b];"
    "[a]adelay=17,vibrato=f=0.4:d=0.5,atrim=start=0.006,asetpts=PTS-STARTPTS[l];"
    "[b]adelay=19,vibrato=f=0.55:d=0.36,atrim=start=0.006,asetpts=PTS-STARTPTS[r];"
    "[l][r]amerge=inputs=2[w]"
)
DOUBLE_SHARE = 10 ** (-15 / 20)
# Стиль — набор эффектов, названный по звучанию словом, которое понятно без
# знания сведения: человек, не отличающий компрессор от эквалайзера, выбирает,
# как ему слышится. Не жанр и не «как у X»: чужой звук не копируем.
# Отзвук — (секунды, доля), дилей — (вид, доля), доля — громкость шины
# к сухому голосу. В роликах владелец взял втрое меньше (reels.REVERB_SHARE),
# но там голос один, а здесь под ним плотный бит.
STYLES = {
    "чисто": {"about": "голос сверху, немного воздуха",
              "reverb": (0.8, 0.07), "delay": ("коротко", 0.05)},
    "мелодично": {"about": "автотюн, широкий отзвук и эхо в темп", "autotune": True,
                  "reverb": (1.2, 0.12), "delay": ("в темп", 0.08)},
    "грязно": {"about": "перегруз и узкая полоса", "color": DIRT,
               "reverb": (0.8, 0.04), "delay": ("коротко", 0.05)},
    "близко": {"about": "сухо и плотно, голос у самого уха, с даблом", "dense": True, "double": True},
}
# Автотюн — x42 fat1 из apt-пакета x42-plugins. Проба в Actions 22.09.2026: в ffmpeg
# 6.1 из apt есть и lv2, и ladspa, грузятся и fat1, и autotalent, но fat1 ставит
# ноту точно (ровный синус — ±0,1 Гц от ноты), а autotalent — на 11–25 центов
# ниже: его детектор завышает высоту, и голос звучал бы фальшиво к биту. Скорость
# 0,02 с — самая быстрая у fat1: ретюн у Lil Uzi Vert 5–20 мс, до 50 мс звучит
# естественно (Sound On Sound, Antares). Ноты — тональности, которую назвал автор бита
# (key_notes): без неё голос тянется к ближайшему из двенадцати полутонов. Плагин моно, поэтому голос
# сводится в одну дорожку и обратно; задержку в 1056 отсчётов ffmpeg 6.1 не снимает —
# её убирают apad и atrim. Двоеточие в адресе плагина экранировано для обоих уровней
# разбора фильтра. На Маке ffmpeg собран без lv2 — там стиль идёт без автотюна.
AUTOTUNE = (r"apad=pad_len=1056,pan=mono|c0=0.5*c0+0.5*c1,"
            r"lv2=p=http\\://gareus.org/oss/lv2/fat1:c=mode=2|tuning=440|corr={corr}|filter={filter}|bias={bias}|fastmode=0|offset=0|{notes},"
            r"pan=stereo|c0=c0|c1=c0,atrim=start_sample=1056,asetpts=N/SR/TB")
NOTES = "до до# ре ре# ми фа фа# соль соль# ля ля# си".split()
# Мягкость автотюна — три положения ручки soft: (corr, filter, bias) плагина x42 fat1, он же
# zita-at1. bias — удержание текущей ноты (при 1 — до 1/13 октавы): без него голос у границы
# двух нот мгновенно перескакивает туда и обратно. filter (0,02–0,5 с) — сглаживание внутри
# ноты; переход между нотами у плагина всегда мгновенный. corr — доля исправления. «мягко» —
# filter 0,1 и bias 0,5, значения плагина по умолчанию. На слух не проверено: плагина на Маке
# нет. Новому треку — «средне» (KNOBS; владелец 09.10.2026 выбрал по описанию, на слух не сравнивал).
# Первое положение, «жёстко», — как было до ручки: записи без неё сведены так, и пересборка
# тюн им не меняет. Числа — в пределах плагина (filter 0,02–0,5, bias и corr 0–1), это держит селфтест.
SOFT = {"жёстко": (1, 0.02, 0), "средне": (1, 0.05, 0.25), "мягко": (0.8, 0.1, 0.5)}

# --- саунд-дизайн -----------------------------------------------------------
# Огибающая для сетки бита и строк голоса — по 10 мс.
ENV_RATE = 100
# Голос звучит, пока громче своего почти самого громкого места минус VOICE_RANGE дБ.
VOICE_RANGE = 30.0
# Саунд-дизайн сдержанный: 3–5 мест на трек, все — на удар бочки, а переходы —
# только там, где бит меняется сам. Прослушка 2 дала «его мало, вообще будто нет»,
# и эффекты разошлись по всему треку; 29.09 владелец: «порой эффект слишком сильный
# и немного не впопад». Всё синтезом ffmpeg, без чужих сэмплов, на доли бита (grid).
# Вдох: слово задом наперёд уходит в отзвук на BREATH_SECONDS, отзвук разворачивается
# обратно и нарастает к слову за BREATH_BEATS долей. Только перед первым словом;
# громкость — BREATH_DB LU к голосу. До 30.09 она шла к биту (−2 LU), и у «Асапчика»,
# где голос на 9 дБ тише бита, вдох выходил громче самого голоса на 7 дБ. Шина вдоха
# тихая (у «Асапчика» −79 LUFS) и меряется _quiet: с прежним замером, который ниже −70
# не видел, −8 здесь на деле были −17 — эта громкость и оставлена.
BREATH_SECONDS = 2.5
BREATH_BEATS = 2
BREATH_DB = -17.0
# Бит до первого слова: за FILTER_BEATS долей закрывается фильтром до FILTER_LOW Гц
# и за OPEN_BEATS долей открывается к сильной доле первого слова.
FILTER_LOW = 400
FILTER_BEATS = 8
OPEN_BEATS = 2
# Свой дроп бита: низ до 150 Гц (бочка и бас) за это окно вырастает на OWN_DROP дБ
# и больше — тогда фильтра нет. У Little Chicago's Finest бочка и бас входят на 8 с,
# за 1,7 с до первого слова (низ −65 → −29 дБ), и фильтр глушил готовый дроп —
# владелец 22.09: «эффект саунд-дизайна вообще лишний и безвкусный». У остальных
# четырёх треков низ в окне ровный (±5 дБ) или бит молчит.
OWN_DROP = 12.0
# Фразы для саунд-дизайна размечаются строже, чем окна с голосом: эдлибы, подпевки
# и хвосты отзвука в стеме тише главного голоса на 15 дБ и больше. С общим порогом
# (VOICE_RANGE) у Little Chicago's Finest на 4:41 выходило 5 строк без единой паузы
# длиннее 0,8 с; с PHRASE_RANGE и паузой от PHRASE_PAUSE — 35 фраз, и четыре самые
# длинные паузы, 0,65–0,81 с, — ровно начала частей трека.
PHRASE_RANGE = 15.0
PHRASE_PAUSE = 0.25
# Броски: последнее слово фразы — в дилей в темп (_tempo_delay), на слово, за которым
# пауза (iZotope: «throws … only certain words»). Не больше THROWS на трек и не чаще
# раза в THROW_BARS тактов — на двух фразах подряд не бывает. Первыми — строки прямо
# перед сменой в бите (вошли или ушли бочка и бас), дальше — перед самыми длинными
# паузами. Первый повтор встаёт на удар бочки в паузе, не дальше такта после слова;
# удара там нет — нет и броска. Громкость — THROW_DB LU к голосу: до 30.09 броски
# шли на 1 LU тише бита, их было до 12 и повтор шёл от самого слова — мимо удара.
# Повторы приседают под всем голосом (Bainz о Young Thug в Sound On Sound: дилей
# «side-chained to the vocal, so it only sounds when the vocal isn't there»).
THROW_WORD = 0.4
THROWS = 2
THROW_BARS = 8
THROW_DB = -12.0
# Телефон — полоса 250 Гц – 2 кГц (SOS, Vocal FX), только коротким проходом: на целой
# партии он «would sound odd». Один на трек — до PHONE_LINES строк прямо перед первым
# дропом бита, где бочки и баса ещё нет, и голос открывается ровно на удар дропа.
# На голом лиде посреди куплета его нет: 29.09 там он звучал слабо.
PHONE = "highpass=f=250,highpass=f=250,lowpass=f=2000,lowpass=f=2000"
PHONE_LINES = 2
# Остановка плёнки: с последней доли, где бит ещё играет в полную силу, скорость
# падает до нуля за STOP_BEATS долей.
STOP_BEATS = 2

# --- мастер -----------------------------------------------------------------
# Низ ниже 120 Гц — в моно: бока бита и отзвука там только мутят и пропадают
# в телефоне и клубе, где низ из одного динамика.
LOW_MONO = f"{MS},highpass=f=120:c=FR,highpass=f=120:c=FR,{LR}"
# Перевёрнутый канал бита ищется там же, ниже 120 Гц: низ у сведённого бита в моно, связь
# каналов около +1, и около −1 она только у перевёрнутого канала. По слышимой полосе
# (60 Гц – 12 кГц) решать нельзя: у бита с противофазным пэдом и моно-808 она −0,37, канал
# переворачивался, 808 уходил в бока, и мастер срезал его — низ до 80 Гц −14,4 дБ на входе
# и −49,5 в мастере (аудит 03.10.2026).
LOW_BAND = f"{FORMAT},lowpass=f=120,lowpass=f=120,"
# Громкость — в ряду рэп-мастеров (−10…−6 LUFS у инженеров из Mix With
# The Masters и Sound On Sound). Пик −2 dBTP: Spotify требует его от мастера
# громче −14 LUFS, иначе при выравнивании громкости трек исказится.
# С этим потолком громкость и удар спорят: пик к громкости (PLR) не больше
# CEILING − MASTER_LUFS. У релизов PLR 9,8 дБ (40 релизов, квартили 9,2…10,8)
# при −9,8 LUFS (−11,6…−9,1), а мастер на −10 давал 8,1: сведение выходило сжатее
# своего релиза на 1,75 дБ (экзамен 28.09.2026, квартили −2,9…−1,1) — клиппер
# и ограничитель срезали удар. −11 — ещё в ряду релизов, а удару 1 дБ возвращается;
# площадки с выравниванием громкости (Spotify, Apple Music, YouTube) всё равно
# приводят трек к −14, и там тише не станет. На −11 сведение сжатее релиза на 0,85 дБ
# (квартили −2,0…−0,3).
MASTER_LUFS = -11.0
CEILING = -2.0
# Сырые барабаны выше громкости на 15–17 дБ, и один ограничитель давил бы
# на ударах по 6 дБ и больше — насосом на весь трек. Верхушки ударов до CLIP дБ
# над порогом срезает клиппер: на миллисекундном ударе искажение не слышно.
# У готового бита с YouTube пики и так низкие, и клиппер почти не работает.
# Клиппер жёсткий: мягкие (asoftclip tanh и atan) на той же громкости и том же пике
# держат удар хуже — они гнут всю волну с нескольких дБ ниже потолка, а не одни
# верхушки. Замер по ударам бочки у Little Chicago's Finest на −10 LUFS и −2 dBTP:
# верхушка удара к окружению теряет 1,4 дБ с жёстким, 1,9 с tanh и 2,5 с atan,
# атака бочки к телу — 0,4 / 0,8 / 0,9 дБ, остаток искажений −24 / −22 / −19 дБ;
# у M.E.R.C. Music верхушка — 0,7 / 1,2 дБ (жёсткий / tanh). Низ ниже 100 Гц у всех
# один (±0,1 дБ): «жёсткий съедает бас» (Шеперд) — о клиппинге на много дБ, а тут два.
CLIP = 2.0
CLIPPER = "asoftclip=type=hard"
# Склейка шины перед клиппером — компрессор 2:1, атака 30 мс, отпуск 200 мс: атака
# пропускает удар, отпуск успевает за долей, и голос с битом сжимаются вместе, а не
# каждый сам по себе. Порог — по замеру, чтобы сжатие было GLUE дБ по EBU R128
# (на пяти треках вышло 1,6–1,7).
GLUE = 1.5
# «Как у <артиста>» — подгонка к 30-секундному превью его трека в магазине: октавы
# микса к 1 кГц, стороны к середине и громкость. Не Matchering: у того подгонка
# без предела, и чужой мастер перекраивал бы трек целиком, а здесь только наклон —
# колокола не больше LIKE_TONE дБ, стороны не больше LIKE_WIDTH, громкость в LIKE_LUFS.
# Превью — кусок трека, обычно припев: для наклона тембра и ширины его хватает.
# Громкость — его EBU R128, но не выше MASTER_LUFS (владелец, 03.10.2026): на −9 LUFS
# кодек площадки поднимал пик выше нуля (AAC 128 кбит/с +0,7 dBTP, MP3 +0,5),
# на −11 — −0,4 и −1,3.
LIKE_TONE = 3.0
LIKE_WIDTH = 3.0
LIKE_LUFS = (-12.0, MASTER_LUFS)
LIKE_PASSES = 2
# Стороны — выше 150 Гц: ниже 120 мастер и так сводит в моно.
LIKE_BAND = "highpass=f=150,"
# Голос на чужом бите (swap): дальше чем на 8 % по темпу его не тянем — растянутый голос
# плывёт. Темп мерит grid: тот же бит, ускоренный на 5 %, он 01.10.2026 узнал в 28 случаях
# из 30, а два промаха (×1,27 и ×1,40) — за этим пределом, то есть отказ, а не голос мимо долей.
SWAP_TEMPO = 0.08


def _ffmpeg(*args) -> None:
    clips.run([clips.ffmpeg(), "-y", "-hide_banner", *map(str, args)])


def _stderr(*args) -> str:
    return subprocess.run([clips.ffmpeg(), "-hide_banner", "-nostats", *map(str, args), "-f", "null", "-"],
                          capture_output=True, text=True).stderr


def loudness(path: Path, chain: str = "") -> tuple[float, float]:
    """Громкость по EBU R128 и истинный пик: (LUFS, dBTP). Тишина — (−70, −inf)."""
    err = _stderr("-i", path, "-af", f"{chain}ebur128=peak=true:framelog=quiet")
    level = re.findall(r"I:\s+(-?[\d.]+) LUFS", err)
    peak = re.findall(r"Peak:\s+(-?[\d.]+|-inf) dBFS", err)
    return (float(level[-1]) if level else -70.0), (float(peak[-1]) if peak else -math.inf)


def _quiet(path: Path) -> float:
    """Громкость тихой шины, LUFS. EBU R128 ниже −70 LUFS не меряет вовсе, и loudness отвечает
    −70, а отзвук бэков там и живёт: посыл на −35…−45 LUFS, свёртка ещё на 35 дБ тише. В заявке
    владельца 01.10.2026 шина была на −73,9, поправка считалась от −70, и отзвук вышел на 3,9 дБ
    тише задуманного, на тех же голосах с другим битом — на 10,4. Тихое меряется поднятым на 40 дБ."""
    level = loudness(path)[0]
    return level if level > -50 else loudness(path, "volume=40dB,")[0] - 40


def _broken(path: Path) -> bool:
    """Есть ли в звуке NaN или бесконечность: громкость по EBU R128 их не всегда видит."""
    err = _stderr("-i", path, "-af", "astats=measure_perchannel=none:measure_overall=Number_of_NaNs+Number_of_Infs")
    return any(float(n) for n in re.findall(r"Number of (?:NaNs|Infs): (\S+)", err))


def _channels(path: Path, chain: str = "") -> list[float]:
    """Громкость каждого канала, дБ RMS. Тишина — −150."""
    err = _stderr("-i", path, "-af", f"{chain}astats=measure_perchannel=RMS_level:measure_overall=none")
    return [max(-150.0, float(db)) for db in re.findall(r"RMS level dB: (-?[\d.]+|-inf)", err)]


def stereo(path: Path, chain: str = "") -> tuple[float, float]:
    """Корреляция каналов и потеря громкости в моно, LU.

    Корреляция — 1 у моно, 0 у несвязанных каналов, меньше нуля — противофаза,
    которая в моно (телефон, колонка) гасит сама себя.
    """
    mid, side = (10 ** (db / 10) for db in _channels(path, f"{chain}{MS},")[:2])
    folded = f"{chain}pan=stereo|c0=0.5*c0+0.5*c1|c1=0.5*c0+0.5*c1,"
    return (mid - side) / (mid + side), loudness(path, chain)[0] - loudness(path, folded)[0]


def _center(vocal: Path) -> str:
    """Голос из одного канала стерео — в оба; иначе ничего."""
    left, right = _channels(vocal, f"{FORMAT},")[:2]
    loud = int(right > left)
    return f"pan=stereo|c0=c{loud}|c1=c{loud}," if abs(left - right) > LOPSIDED else ""


def tone(path: Path, chain: str) -> dict[int, float]:
    """Октавы голоса к полосе 1 кГц, дБ, за один проход.

    Полосы режутся крутыми фильтрами, 36 дБ на октаву: у пологих соседняя
    протекает, и гул 250 Гц читался бы в полосе 125.
    """
    bands = [*TONE, 1000]
    graph = (
        f"[0:a]{chain},asplit={len(bands)}{''.join(f'[i{f}]' for f in bands)};"
        + "".join(
            f"[i{f}]" + ",".join([f"highpass=f={f / 2 ** 0.5:.0f}"] * 3 + [f"lowpass=f={min(f * 2 ** 0.5, 20000):.0f}"] * 3)
            + f",astats@{f}=measure_perchannel=none:measure_overall=RMS_level[o{f}];"
            for f in bands
        )
        + "".join(f"[o{f}]" for f in bands) + f"amix=inputs={len(bands)}"
    )
    level = {int(f): float(db) for f, db in re.findall(
        r"\[astats@(\d+) @ \w+\] RMS level dB: (-?[\d.]+|-inf)", _stderr("-i", path, "-filter_complex", graph))}
    return {f: level[f] - level[1000] for f in TONE}


def _bells(gains: dict[int, float]) -> str:
    return "".join(f"equalizer=f={f}:t=o:w=1:g={g:.1f}," for f, g in gains.items() if g)


def _equalizer(vocal: Path, lines: list[tuple[float, float]], work: Path, deess: str = DEESSER + ",") -> str:
    """Поправка тембра в пределы TONE колоколами по октавам: общая на весь трек и своя по ходу
    трека — командами asendcmd колоколам equalizer@t…, шагами по 0,1 с, чтобы
    не щёлкало. Меряется голос уже с де-эссером deess (с запятой или пусто), а соседние
    колокола задевают друг друга, поэтому каждый замер повторяется по поправленному голосу."""
    gains, floor = dict.fromkeys(TONE, 0.0), None
    for _ in range(2):
        heard = tone(vocal, _bells(gains) + deess + "anull")
        if floor is None:
            # Тело гудит, если 2 и 4 кГц при этом в своих пределах; за краем и они — провален сам 1 кГц.
            floor = TONE_BODY if all(heard[f] <= TONE[f][1] for f in TONE_PRESENCE) else {}
        for f, db in heard.items():
            gains[f] = max(floor.get(f, TONE_CUT), min(TONE_BOOST.get(f, 0.0), gains[f] + min(max(db, TONE[f][0]), TONE[f][1]) - db))
    print("  тембр: " + ", ".join(f"{f} Гц {g:+.1f}" for f, g in gains.items() if g))
    # Колокол есть и у 1 кГц: поправка окна меняет только форму, а общую мощность
    # окна возвращает он — иначе окна, где 1 кГц провален, теряли бы громкость
    # целиком, и райдер поднимал бы голос вдвое чаще (у Little Chicago's Finest бит
    # перекрывал голос в 37% окон вместо 20%).
    octaves = sorted([*TONE, 1000])
    cmd, local = work / "tone.cmd", "".join(f"equalizer@t{f}=f={f}:t=o:w=1:g=0," for f in octaves)
    extra, ref, drift = {f: {} for f in octaves}, {}, []
    split = [f / 2 ** 0.5 for f in octaves] + [octaves[-1] * 2 ** 0.5]
    for again in range(2):
        chain = _bells(gains) + (f"asendcmd=f='{cmd}',{local}" if again else "") + f"{deess}{MID},"
        power = dict(zip(octaves, ([10 ** (db / 10) for db in band] for band in _bands(vocal, chain, split, TONE_STEP)[1:])))
        sung = _sung(lines, len(power[1000]), TONE_STEP)
        if not sung:
            return _bells(gains)
        ref = ref or {f: 10 * math.log10(sum(power[f][i] for i in sung) / sum(power[1000][i] for i in sung)) for f in TONE}
        miss = []
        for w in sung:
            near = [i for i in sung if abs(i - w) * TONE_STEP <= TONE_SPAN / 2]
            total = {f: sum(power[f][i] for i in near) + 1e-15 for f in octaves}
            shape = {f: ref.get(f, 0.0) - 10 * math.log10(total[f] / total[1000]) for f in octaves}
            level = -10 * math.log10(sum(total[f] * 10 ** (shape[f] / 10) for f in octaves) / sum(total.values()))
            miss += [abs(shape[f]) for f in TONE]
            for f in octaves:
                # Вверх — не выше TONE_BOOST, как и общая; у 1 кГц общего колокола нет.
                top = TONE_BOOST.get(f, 0.0) - gains[f] if f in TONE else TONE_LOCAL
                extra[f][w] = max(-TONE_LOCAL, min(TONE_LOCAL, top, extra[f].get(w, 0.0) + shape[f] + level))
        drift.append(statistics.fmean(miss))
        # Между окнами с голосом — по прямой, до первого и после последнего — как у них.
        times, rows, sent = [(w + 0.5) * TONE_STEP for w in sung], [], {}
        for n in range(round(len(power[1000]) * TONE_STEP * 10) + 1):
            t, row = n / 10, []
            k = min(max(0, sum(x <= t for x in times) - 1), len(times) - 2)
            for f in octaves:
                a, b = extra[f][sung[k]], extra[f][sung[min(k + 1, len(sung) - 1)]]
                share = 0.0 if len(times) < 2 else min(1.0, max(0.0, (t - times[k]) / (times[k + 1] - times[k])))
                value = round(a + (b - a) * share, 1)
                if sent.get(f) != value:
                    sent[f] = value
                    row.append(f"equalizer@t{f} g {value}")
            if row:
                rows.append(f"{t:.1f} " + ", ".join(row) + ";")
        cmd.write_text("\n".join(rows))
    reach = {f: (min(extra[f].values()), max(extra[f].values())) for f in octaves}
    print(f"  тембр по ходу: окна отходили от среднего на {drift[0]:.1f} дБ, после поправки — на {drift[1]:.1f}; "
          + ", ".join(f"{f} Гц {lo:+.1f}…{hi:+.1f}" for f, (lo, hi) in reach.items()))
    return _bells(gains) + f"asendcmd=f='{cmd}',{local}"


def _envelope(path: Path, chain: str = "") -> list[float]:
    """Уровень по 10 мс, дБ: средний модуль сигнала, сведённого в моно."""
    raw = subprocess.run([clips.ffmpeg(), "-v", "error", "-i", str(path), "-af", f"{chain}aresample=4000",
                          "-ac", "1", "-f", "f32le", "-"], capture_output=True, check=True).stdout
    x, step = array.array("f", raw), 4000 // ENV_RATE
    return [20 * math.log10(sum(map(abs, x[i:i + step])) / step + 1e-6) for i in range(0, len(x) - step + 1, step)]


def _rise(path: Path, chain: str) -> list[float]:
    """Удары: рост уровня за 20 мс по 10 мс, к среднему — полосы сравнимы между собой."""
    level = _envelope(path, chain)
    rise = [0.0, 0.0] + [max(0.0, level[i] - level[i - 2]) for i in range(2, len(level))]
    mean = statistics.fmean(rise) or 1.0
    return [r / mean for r in rise]


def grid(beat: Path) -> tuple[float, float]:
    """Сетка бита: длина доли и где сильная доля такта, секунды.

    Меряется минута с начала места, где качает низ (reels.beat_start). Темп — в пределах
    60–120 ударов в минуту: быстрый бит считается вдвое медленнее, и каждая доля
    сетки остаётся сильной. Темп — автокорреляция ударов на долю и на две, три,
    четыре доли вперёд, по всей полосе, по низу, где бочка и 808, и по верху (от 150 Гц
    до 2 кГц: уровень меряется на 4 кГц, хэтов в нём нет), одно на другое: мягкий бит
    Coruscate по низу не читается вовсе (низ равен на всех темпах, и решают остальные),
    а где бочка держит пульс, решает она. Верх в счёте с 06.10.2026: 808 играет и свой
    рисунок мимо доли, и на бите ручного заказа, где кроме него почти ничего нет, вся
    полоса с низом выбрали 64,3 вместо 104,5 — броски и дилей ушли из такта. Убрать низ
    нельзя: по одной всей полосе столько же битов портится, сколько чинится.
    Одна автокорреляция по низу с шагом 10 мс дала Coruscate 82,6 вместо 80 — к концу
    трека эхо ушло бы с доли, — поэтому темп и первая доля уточняются гребёнкой с шагом
    0,01 удара в минуту, и по всему биту, а не по минуте: сетка тянется от сильной доли
    на весь трек, а автокорреляция ошибается на 0,3–0,4 удара (у того же бита 104,8 —
    за сто секунд это две шестнадцатых). Шире ±0,4 искать нельзя: на бите в полминуты
    гребёнка уходит за шумом. Выбирать гребёнкой и сам темп нельзя: на медленной сетке
    лежат только самые громкие удары, и у M.E.R.C. Music она выбрала 80 вместо 107.
    Первая доля — сильная доля такта: из четырёх фаз сетки та, где сильнее бьёт
    низ (бочка), и такты — через каждые четыре доли от неё.
    """
    offset = reels.beat_start(beat)
    cut = f"atrim=start={offset:.2f}:duration=60,"
    full, low, high = (_rise(beat, cut + band) for band in ("", "lowpass=f=120,lowpass=f=120,", "highpass=f=150,highpass=f=150,"))

    def score(rise: list[float]) -> list[float]:
        acf = [sum(a * b for a, b in zip(rise, rise[k:])) for k in range(ENV_RATE * 4 + 2)]
        return [sum(acf[int(m * p)] + (acf[int(m * p) + 1] - acf[int(m * p)]) * (m * p % 1) for m in range(1, 5))
                for p in (60 * ENV_RATE / bpm for bpm in BPM)]

    every = [f * lo * hi for f, lo, hi in zip(score(full), score(low), score(high))]
    bpm = BPM[max(range(len(BPM)), key=every.__getitem__)]
    whole = _rise(beat, "")

    def comb(period: float) -> tuple[float, float, int]:
        return max((statistics.fmean(whole[round(s + k * period)] for k in range(int((len(whole) - 1 - s) / period) + 1)),
                    period, s) for s in range(int(period)))

    _, period, start = max(comb(60 * ENV_RATE / (bpm + d / 100)) for d in range(-40, 41))
    start = (start - offset * ENV_RATE) % period  # гребёнка считала от начала файла, низ ниже — от начала минуты

    def kick(phase: int) -> float:
        return statistics.fmean(low[round(start + (4 * k + phase) * period)]
                                for k in range(int((len(low) - 1 - start - phase * period) / (4 * period)) + 1))

    return period / ENV_RATE, offset + (start + max(range(4), key=kick) * period) / ENV_RATE


BPM = [60 + 0.1 * i for i in range(601)]


# Профили тональностей Темперли (Kostka — Payne): насколько каждая ступень звучит
# «своей» в мажоре и миноре, от тоники. До 09.10.2026 стояли профили Крумхансла — Кесслер
# и сумма мощностей полос: на 67 битах и петлях с тональностью от автора набор нот
# совпал у 23. С Темперли и корнем четвёртой степени из мощности полосы — у 37:
# громкая нота баса больше не перекрикивает остальные.
MAJOR = [0.748, 0.060, 0.488, 0.082, 0.670, 0.460, 0.096, 0.715, 0.104, 0.366, 0.057, 0.400]
MINOR = [0.712, 0.084, 0.474, 0.618, 0.049, 0.460, 0.105, 0.747, 0.404, 0.067, 0.133, 0.330]
# Порог уверенности замера — запас корреляции между лучшим набором нот и следующим.
# None: порога нет, и замер нот не называет. 09.10.2026 на тех же 67 файлах запас верные
# ответы от неверных не отделил (медиана у верных 0,08, у неверных 0,10): точных среди
# «уверенных» 53–67 % при любом пороге (от 0,2 — 7 из 11), а нужно не меньше 85 %. Согласие
# трёх профилей (16 из 21) и кусков трека (12 из 17) — тоже мимо. Чужая нота в наборе —
# фальшь в готовом треке, поэтому семь нот бот берёт только со слов автора бита (key_notes).
SCALE_SURE: float | None = None

SCALES = {"maj": (0, 2, 4, 5, 7, 9, 11), "min": (0, 2, 3, 5, 7, 8, 10), "phr": (0, 1, 3, 5, 7, 8, 10), "dor": (0, 2, 3, 5, 7, 9, 10),
          "lyd": (0, 2, 4, 6, 7, 9, 11), "mix": (0, 2, 4, 5, 7, 9, 10), "loc": (0, 1, 3, 5, 6, 8, 10)}
TONICS = {"c": 0, "d": 2, "e": 4, "f": 5, "g": 7, "a": 9, "b": 11, "до": 0, "ре": 2, "ми": 4, "фа": 5, "соль": 7, "ля": 9, "си": 11}
# Тональность в имени файла бита: «140 Fm», «F# min», «Cmin», «B MAJOR», «F# PHRY», «фа минор».
# Нота латиницей — только заглавной, одиночная «m» — только строчной и не перед цифрой: иначе
# тональностью стали бы «5 AM», «FM radio» и аккорд «Dm7». Буква без лада («SixStr120B-01») и
# слог внутри слова («Amsterdam») — не тональность; «I Am» и «Am I» — тоже. Буква — любая
# ([^\W\d_]), а не только латиница с кириллицей: иначе «Aminé type beat» — ля минор.
# Имя артиста тональностью не считается: «A Major Lazer», а слитные «Amin» и «Emin» — перед
# тире, «&», «x», «type» и «feat» («Emin — Трек», «Amin type beat»). Сами по себе они тональность:
# так её пишут банки («GV_VocPad_140-Amin» в наборе 11). Цена — «Amin - 140.wav» останется без
# нот: бот попросит назвать тональность словами, а чужая нота в наборе — фальшь в готовом треке.
# Файл с одним именем «Emin.mp3» от ми минора не отличить — он читается тональностью.
KEY = re.compile(
    r"(?<![^\W\d_])(?<![#♯♭])(?<!\bI )(?:(?P<note>[A-G])(?P<mark>[#♯b♭]|[ -]?(?i:sharp|flat))?"
    r"(?:(?P<m>m)(?!\d)|[ _-]?(?P<mode>(?i:major|maj|minor|min|миноре?|мажоре?|phrygian|phry|dorian|lydian|mixolydian|locrian)))"
    r"|(?i:(?P<nota>до|ре|ми|фа|соль|ля|си)[ -]?(?P<znak>диез|бемоль)?[ -](?P<lad>миноре?|мажоре?)))(?![^\W\d_])(?! I\b)"
    r"(?![ _]+(?i:lazer))(?!(?<=(?i:[ae]min))[ _]+(?:[-–—&]|(?i:x|type|feat|ft)(?![^\W\d_])))")


def key_notes(name: str) -> list[int] | None:
    """Ноты тональности, которую автор бита назвал в имени файла или подписи; не назвал — None.

    Словам автора вера выше замера: на 57 именах с тональностью набор нот верен у всех 57,
    на 5300 именах звуков, петель и битов без неё ложных срабатываний нет (09.10.2026).
    Лады — мажор, минор, фригийский, дорийский, лидийский, миксолидийский, локрийский."""
    found = KEY.search(name)
    if not found:
        return None
    mark = (found["mark"] or found["znak"] or "").strip(" -").lower()
    tonic = TONICS[(found["note"] or found["nota"]).lower()] + (mark in ("#", "♯", "sharp", "диез")) - (mark in ("b", "♭", "flat", "бемоль"))
    mode = (found["m"] or found["mode"] or found["lad"]).lower()[:3]
    return sorted((tonic + step) % 12 for step in SCALES[{"m": "min", "мин": "min", "маж": "maj"}.get(mode, mode)])


def scale(beat: Path) -> list[int]:
    """Ноты тональности бита по звуку, 0 — до; не уверен — все двенадцать.

    Громкость каждого полутона от до большой октавы до си второй — узкими
    полосами за один проход ffmpeg, по октавам в сумму, и сравнение с профилями
    MAJOR и MINOR на всех двенадцати тониках. Параллельные мажор и минор делят
    одни ноты, поэтому уверенность — запас корреляции до лучшей тональности
    с другим набором нот. Запас меньше SCALE_SURE — ответ «все полутона»: с ними
    автотюн тянет голос к ближайшему полутону, и чужой ноты не бывает. Пока порога
    нет (SCALE_SURE), бит не меряется вовсе.
    """
    if SCALE_SURE is None:
        return list(range(12))
    notes = range(36, 84)
    graph = (f"[0:a]pan=mono|c0=0.5*c0+0.5*c1,asplit={len(notes)}" + "".join(f"[i{n}]" for n in notes) + ";"
             + "".join(f"[i{n}]" + f"bandpass=f={440 * 2 ** ((n - 69) / 12):.2f}:t=q:w=25," * 2
                       + f"astats@{n}=measure_perchannel=none:measure_overall=RMS_level[o{n}];" for n in notes)
             + "".join(f"[o{n}]" for n in notes) + f"amix=inputs={len(notes)}")
    chroma = [0.0] * 12
    for n, db in re.findall(r"\[astats@(\d+) @ \w+\] RMS level dB: (-?[\d.]+)", _stderr("-i", beat, "-filter_complex", graph)):
        chroma[int(n) % 12] += 10 ** (float(db) / 40)
    if len(set(chroma)) < 2:  # тишина: сравнивать нечего
        return list(range(12))
    best: dict[tuple[int, ...], float] = {}
    for tonic in range(12):
        for profile, steps in ((MAJOR, SCALES["maj"]), (MINOR, SCALES["min"])):
            found = tuple(sorted((tonic + step) % 12 for step in steps))
            best[found] = max(best.get(found, -1.0), statistics.correlation([chroma[(tonic + i) % 12] for i in range(12)], profile))
    (found, top), (_, second) = sorted(best.items(), key=lambda pair: -pair[1])[:2]
    return list(found) if top - second >= SCALE_SURE else list(range(12))


def _on_grid(t: float, beat: tuple[float, float], how=round) -> float:
    """Доля сетки у момента t: ближайшая (round), следующая (math.ceil) или прошлая (math.floor)."""
    length, start = beat
    return start + how((t - start) / length) * length


def _lines(level: list[float], below: float = VOICE_RANGE, pause: float = 0.4) -> list[tuple[float, float]]:
    """Строки голоса по огибающей: (начало, конец), секунды. Голос — громче почти
    самого громкого места минус below дБ; паузы короче pause — внутри строки,
    щелчки короче 0,1 с — не голос."""
    top, lines = sorted(level)[int(len(level) * 0.95)], []
    for i, db in enumerate(level):
        if db <= top - below:
            continue
        if lines and i - lines[-1][1] < pause * ENV_RATE:
            lines[-1][1] = i + 1
        else:
            lines.append([i, i + 1])
    return [(a / ENV_RATE, b / ENV_RATE) for a, b in lines if b - a >= 0.1 * ENV_RATE]


def swing(path: Path) -> float:
    """Размах голоса внутри строк, дБ: p90 − p10 уровня по 10 мс. Компрессия его
    съедает — тихое между слогами, вдохи и шум поднимаются к слову. Только внутри
    строк: тишина между куплетами иначе дала бы размах в сто дБ у любого голоса."""
    level = _envelope(path)
    inside = sorted(level[i] for a, b in _lines(level) for i in range(int(a * ENV_RATE), int(b * ENV_RATE)))
    return inside[int(0.9 * (len(inside) - 1))] - inside[int(0.1 * (len(inside) - 1))] if inside else 0.0


def _blend(effect: str, share: float, tag: str) -> str:
    """effect параллельно сухому звуку долей share; tag — свои метки в графе."""
    return (f"asplit[{tag}d][{tag}w];[{tag}w]{effect}[{tag}e];"
            f"[{tag}d][{tag}e]amix=inputs=2:weights={1 - share:g} {share:g}:normalize=0")


def _squeeze(source: Path, before: str, dest: Path, after: str = "") -> Path:
    """Голос через VOCAL_CHAIN в dest на SQUEEZED_LUFS: before — цепочка до компрессии
    (срез и громкость к VOCAL_LUFS), after — после. Каждая ступень подмешивается
    параллельно самой большой долей из LEVEL_STEPS, при которой голос не плотнее
    релизов: первая — пик к громкости не ниже VOCAL_PLR, вторая — размах
    не мельче VOCAL_SWING."""
    peaks, leveler = VOCAL_CHAIN
    for first in LEVEL_STEPS:
        head = f"{before},{_blend(peaks, first, 'p')}" if first else before
        level, peak = loudness(source, head + ",")
        if not first or peak - level >= VOCAL_PLR:
            break
    probe = dest.with_name(dest.stem + "-probe.wav")
    for share in LEVEL_STEPS:
        _ffmpeg("-i", source, "-af", f"{head},{_blend(leveler, share, 'l')}", *reels.VOICE_CODEC, probe)
        if not share or (got := swing(probe)) >= VOCAL_SWING:
            break
    print(f"  компрессия: первая ступень на {first:.0%}, вторая на {share:.0%}"
          + (f", размах голоса {got:.1f} дБ" if share else ""))
    _ffmpeg("-i", probe, "-af", f"volume={SQUEEZED_LUFS - loudness(probe)[0]:.2f}dB{after}", *reels.VOICE_CODEC, dest)
    probe.unlink()
    return dest


def hiss(path: Path, chain: str = "") -> float:
    """Шипящие к голосу, дБ: средняя мощность 5–10 кГц в 5% окон по 20 мс, где её доля
    больше всего, к средней мощности голоса. Голос — окна не тише 30 дБ от громких
    (95-й процентиль), иначе тишина между строками сошла бы за голос."""
    low, mid, high = ([10 ** (db / 10) for db in band] for band in _bands(path, chain, (5000, 10000), 0.02))
    total = [sum(w) for w in zip(low, mid, high)]
    loud = sorted(total)[int(0.95 * (len(total) - 1))] / 1000
    sung = sorted((m / t, m, t) for m, t in zip(mid, total) if t >= loud)
    top = sung[int(0.95 * (len(sung) - 1)):]
    return 10 * math.log10(statistics.fmean(m for _, m, _ in top) / statistics.fmean(t for *_, t in sung))


def _deesser(vocal: Path) -> str:
    """Самый сильный де-эссер из DEESS_STEPS, после которого шипящие не тише VOCAL_HISS,
    с запятой в конце; не нужен ни один — пусто."""
    for strength in DEESS_STEPS:
        if (got := hiss(vocal, f"deesser=i={strength},")) >= VOCAL_HISS:
            print(f"  де-эссер: сила {strength:g}, шипящие к голосу {got:.1f} дБ")
            return f"deesser=i={strength},"
    print(f"  де-эссер: не нужен, шипящие к голосу {hiss(vocal):.1f} дБ")
    return ""


def _gain_track(points: list[tuple[float, float]], seconds: float, path: Path) -> Path:
    """Огибающая громкости дорожкой WAV для amultiply: точки (секунда, дБ),
    между ними — по прямой, 1000 отсчётов в секунду.

    WAV из stdlib только целочисленный, а усиление бывает больше единицы,
    поэтому в файле оно вдвое меньше, а _apply умножает обратно — запас до +6 дБ.
    """
    values, j = array.array("h"), 0
    for n in range(int(seconds * 1000) + 1000):
        t = n / 1000
        while j + 1 < len(points) and points[j + 1][0] <= t:
            j += 1
        (t0, g0), (t1, g1) = points[j], points[min(j + 1, len(points) - 1)]
        db = g0 if t1 <= t0 or t <= t0 else g0 + (g1 - g0) * min(1.0, (t - t0) / (t1 - t0))
        values.append(min(32767, round(16384 * 10 ** (db / 20))))
    with wave.open(str(path), "wb") as track:
        track.setnchannels(1)
        track.setsampwidth(2)
        track.setframerate(1000)
        track.writeframes(values.tobytes())
    return path


def _apply(source: Path, track: Path, dest: Path, before: str = "anull") -> Path:
    """Громкость source по огибающей _gain_track. Огибающая короче звука обрежет его."""
    _ffmpeg("-i", source, "-i", track, "-filter_complex",
            f"[0:a]{before}[s];[1:a]aresample={RATE},pan=stereo|c0=c0|c1=c0[g];[s][g]amultiply,volume=2",
            *reels.VOICE_CODEC, dest)
    return dest


def _sum(inputs: list[tuple[Path, float]], dest: Path, before: str = "anull") -> Path:
    """Дорожки с поправками громкости, дБ, — в одну dest; before — цепочка каждой до суммы."""
    _ffmpeg(*(arg for path, _ in inputs for arg in ("-i", path)), "-filter_complex",
            "".join(f"[{n}:a]{before},volume={gain:.2f}dB[s{n}];" for n, (_, gain) in enumerate(inputs))
            + "".join(f"[s{n}]" for n in range(len(inputs)))
            + f"amix=inputs={len(inputs)}:duration=longest:normalize=0", *reels.VOICE_CODEC, dest)
    return dest


def _gaps(vocal: Path, beat: Path, lift: float = 0.0) -> tuple[list[float], list[float | None]]:
    """Голос против бита окнами 0,4 с через каждые 0,1 с: середина окна
    и разница в LU; None — голос в этом окне не звучит."""
    whole, voice = reels.meter(vocal)
    _, under = reels.meter(beat)
    n = min(len(voice), len(under))
    return ([voice[i][0] - 0.2 for i in range(n)],
            [voice[i][1] + lift - under[i][1] if voice[i][1] > whole - RIDE_GATE else None for i in range(n)])


def masked(gaps: list[float | None]) -> float:
    """Доля окон с голосом, где бит громче него больше чем на 2 дБ, %."""
    sung = [gap for gap in gaps if gap is not None]
    return 100 * sum(gap < -2 for gap in sung) / max(len(sung), 1)


def _ride(dry: Path, beat: Path, lift: float, target: float, work: Path) -> Path:
    """Голос с общим подъёмом lift и райдером (RIDE_*) к цели target — голос к биту
    в окне, дБ, — в work/vocal-ride.wav."""
    times, gaps = _gaps(dry, beat, lift)
    want = [0.0 if gap is None else max(0.0, min(RIDE_MAX, target - gap)) for gap in gaps]
    hold, smooth = round(RIDE_HOLD * 5), round(RIDE_SMOOTH * 5)
    peak = [max(want[max(0, i - hold):i + hold + 1]) for i in range(len(want))]
    ride = [statistics.fmean(peak[max(0, i - smooth):i + smooth + 1]) for i in range(len(peak))]
    track = _gain_track(list(zip(times, ride)), clips.probe_seconds(dry) + 1, work / "ride.wav")
    out = _apply(dry, track, work / "vocal-ride.wav", f"volume={lift:.2f}dB")
    print(f"  райдер: бит громче голоса больше чем на 2 дБ в {masked(gaps):.0f}% окон → "
          f"{masked(_gaps(out, beat)[1]):.0f}%, голос поднят в среднем на {statistics.fmean(ride):.1f} дБ")
    return out


def _reverb(seconds: float, before: str = "highpass=f=300,lowpass=f=7000,adelay=25|25", after: str = "anull") -> str:
    """Отзвук, как reels.REVERB, нужной длины: свёртка с розовым шумом, гаснущим
    на 60 дБ за seconds, у каналов шум свой — отзвук вокруг голоса."""
    return (
        f"anoisesrc=r={RATE}:d={seconds}:c=pink:seed=1[n1];"
        f"anoisesrc=r={RATE}:d={seconds}:c=pink:seed=2[n2];"
        f"[n1][n2]amerge=inputs=2,asetnsamples=64,volume='exp(-6.9*t/{seconds})':eval=frame[ir];"
        f"[0:a]{before}[in];[in][ir]afir,{after}[w]"
    )


def _tempo_delay(length: float, under: float | None = None, key: str = "", seconds: float = 0.0) -> str:
    """Дилей в темп от стены к стене: слева повторы через четверть, справа — через
    восьмую (главный и второй у инженеров Sound On Sound), по три с затуханием;
    на возврат — полоса 200 Гц – 5 кГц (Элмхёрст в Mix With The Masters).

    under — громкость голоса, LUFS: под голосом дилей приседает на 8–10 дБ
    (2:1, атака сразу, отпуск 150 мс, как у Сениора) и раскрывается в паузах.
    Иначе повторы ложились бы на следующие слова и мутили их. key — вход с голосом
    для ключа («[1:a]»), если на входе дилея не весь голос, а только броски; с ним
    seconds — длина входа дилея: выход будет ровно такой."""
    head, tail = "[0:a]", "[w]"
    if under is not None:
        duck = f"sidechaincompress=threshold={10 ** ((under - 18) / 20):.4f}:ratio=2:attack=0.01:release=150"
        head, tail = "[0:a]asplit[x][k];[x]", f"[d];[d][k]{duck}[w]"
        if key:
            # Ключ — другой файл, и sidechaincompress закрывает выход с концом любого входа,
            # бросая не дождавшееся пары (как в _room): шина выходила то целой, то на 0,08 с
            # короче, и два сведения одного кода расходились побайтно. Дилей и ключ дополнены
            # тишиной (ROOM_PAD), ключ перед тем — до длины входа seconds: он бывает короче,
            # а бесконечный apad здесь оборвать нечем, кроме конца соседней ветки, — такой
            # связки на ffmpeg сервера не было. Длину возвращает amerge с немой копией входа:
            # он кончает по ней и своего не бросает.
            head = "[0:a]asplit[x][z];[z]volume=0,pan=stereo|c0=c0|c1=c0[mute];[x]"
            tail = (f",{ROOM_PAD}[d];{key}apad=whole_dur={seconds:.2f},{ROOM_PAD}[k];[d][k]{duck}[c];"
                    "[mute][c]amerge=inputs=2,pan=stereo|c0=c2|c1=c3[w]")
    return (
        f"{head}highpass=f=200,lowpass=f=5000,pan=mono|c0=0.5*c0+0.5*c1,asplit[a][b];"
        + "".join(f"[{side}]aecho=in_gain=0:out_gain=1:delays={d:.0f}|{2 * d:.0f}|{3 * d:.0f}"
                  f":decays=0.6|0.36|0.2[{side}{side}];" for side, d in (("a", 1000 * length), ("b", 500 * length)))
        + "[aa][bb]amerge=inputs=2" + tail
    )


def _said(items: list[dict], parts: list[tuple[str, Path, str]], key: str = "") -> tuple[str, list[int]] | None:
    """Тональность со слов — (откуда, ноты): сперва человек (ручка key: он слышит свой трек,
    а имя файла могло приехать от чужого бита), потом подпись бита из каталога ПЛЁНКИ
    (номер бита — ключ b файла), потом имя файла бита. Никто не назвал — None."""
    if notes := key_notes(key):
        return "слова человека", notes
    catalog = state.read_json(config.BEATS_FILE, {})
    for item in items:
        key = (catalog.get(item.get("b") or "") or {}).get("key") or ""
        if notes := key_notes(key[:1].upper() + key[1:]):  # подпись бит принимает и строчными: «fm»
            return "каталог", notes
    return next((("имя файла", notes) for name, _, part in parts if part == "бит" and (notes := key_notes(name))), None)


def _tune(notes: list[int], soft: str) -> str:
    """Строка фильтра автотюна: ноты и мягкость (SOFT). Одна на сведение и на пробу плагина (tune_check)."""
    return AUTOTUNE.format(notes="|".join(f"m{n:02d}={int(n in notes)}" for n in range(12)),
                           **dict(zip(("corr", "filter", "bias"), SOFT[soft])))


def _autotune(beat: Path, said: tuple[str, list[int]] | None = None, soft: str = "", loose: list[str] | None = None) -> str:
    """Автотюн к нотам тональности бита; пусто — ffmpeg этой сборки фильтр не принял.

    said — тональность со слов (_said); без неё — из имени самого файла, потом замер,
    а замер не уверен — все двенадцать полутонов. soft — мягкость (SOFT). loose — сюда отметка,
    что тюн пошёл по двенадцати полутонам: человеку подсказка назвать тональность. В журнал
    идёт только, откуда ноты: имени файла человека там быть не должно."""
    source, notes = said or (("имя файла", named) if (named := key_notes(beat.stem)) else ("замер", scale(beat)))
    if len(notes) == 12:
        source = "не уверен — все полутона"
    soft = soft if soft in SOFT else next(iter(SOFT))
    tune = _tune(notes, soft)
    # Проба — той же строкой с теми же ручками, что пойдёт в сведение: на Маке плагина нет,
    # а значение, которого плагин не принял, уронило бы сведение уже на голосе.
    probe = subprocess.run([clips.ffmpeg(), "-v", "error", "-f", "lavfi", "-i", f"anullsrc=r={RATE}:cl=stereo",
                            "-t", "0.1", "-af", tune, "-f", "null", "-"], capture_output=True)
    if probe.returncode:
        print("  автотюн: ffmpeg фильтр не принял (плагина нет в сборке или ручка вне пределов), стиль идёт без него")
        return ""
    print(f"  автотюн к нотам бита ({source}), {soft}: " + " ".join(NOTES[n] for n in notes))
    if loose is not None and len(notes) == 12:
        loose.append(source)
    return tune


def _band(low: float, high: float, order: int = 3) -> str:
    """Полоса low–high крутыми фильтрами: order раз по 12 дБ на октаву с каждой
    стороны; 0 — без этой стороны."""
    return ",".join([f"highpass=f={low:.0f}"] * order * bool(low) + [f"lowpass=f={high:.0f}"] * order * bool(high)) or "anull"


def _bands(path: Path, chain: str = "", split=SPLIT, step: float = 0.1, cuts: list[str] | None = None) -> list[list[float]]:
    """Уровень полос по окнам step секунд, дБ RMS, за один проход: полосы между
    частотами split, 36 дБ на октаву, как в tone, нулевая — ниже первой частоты.
    cuts — свои фильтры полос вместо split. Тишина — −150."""
    edges = (0, *split, 0)
    cuts = cuts or [_band(edges[k], edges[k + 1]) for k in range(len(edges) - 1)]
    n = len(cuts)
    graph = (f"[0:a]{chain}asplit={n}" + "".join(f"[i{k}]" for k in range(n)) + ";"
             + "".join(f"[i{k}]{cuts[k]},asetnsamples={round(RATE * step)},astats=metadata=1:reset=1:"
                       f"measure_perchannel=none:measure_overall=RMS_level,"
                       f"ametadata@{k}=print:key=lavfi.astats.Overall.RMS_level[o{k}];" for k in range(n))
             + "".join(f"[o{k}]" for k in range(n)) + f"amix=inputs={n}")
    levels = [[] for _ in range(n)]
    for k, db in re.findall(r"\[ametadata@(\d+) @ \w+\] lavfi\.astats\.Overall\.RMS_level=(-?[\d.]+|-inf)",
                            _stderr("-i", path, "-filter_complex", graph)):
        levels[int(k)].append(max(-150.0, float(db)))
    return levels


def _sung(lines: list[tuple[float, float]], n: int, step: float) -> list[int]:
    """Окна по step секунд, середина которых — в строке голоса."""
    return [i for i in range(n) if any(a <= (i + 0.5) * step < b for a, b in lines)]


MID = "pan=mono|c0=0.5*c0+0.5*c1"


def _room(beat: Path, dry: Path, head: str, lift: float, lines: list[tuple[float, float]], work: Path) -> Path:
    """Бит с местом голосу — в work/beat.wav: полосы середины SPLIT приседают ключом
    от тех же полос голоса (ROOM_*). head — цепочка бита до M/S, lift — на сколько
    голос в сведении громче себя сухого против бита, дБ.

    Провал — разность «сжатая полоса − полоса», прибавленная к целой середине:
    без голоса она ноль, и бит выходит бит в бит (замер: −146 дБ), а бока не тронуты
    вовсе. Полоса для провала — bandpass второго порядка на октаву: у него
    вещественная часть равна квадрату модуля, и x − k·BP(x) — честный колокол
    вниз; у крутых фильтров фаза на краях полосы уходит за 90°, и та же разность
    там поднимала бит (+0,1 дБ на куске с голосом вместо провала). Ключу крутизна
    нужна — он крутыми фильтрами. acrossover с sidechaincompress в ffmpeg 8.1
    зависал в половине прогонов (docs/research/2026-09-22/asap-rocky.md), фильтры —
    ни разу."""
    under, over = _bands(beat, f"{head}{MID},"), _bands(dry, f"{MID},")
    sung = _sung(lines, min(len(under[0]), len(over[0])), 0.1)
    depth, key = {}, {}
    for b in range(1, len(SPLIT) + 1):
        gap = statistics.median(over[b][i] + lift - under[b][i] for i in sung) if sung else ROOM_GAP[b - 1]
        cut = max(0.0, min(ROOM_CAP[b - 1], ROOM_GAP[b - 1] - gap))
        if cut:
            depth[b], key[b] = cut, statistics.median(over[b][i] for i in sung) - cut * ROOM_RATIO / (ROOM_RATIO - 1)
    out = work / "beat.wav"
    if not depth:
        print("  место голосу: голос стоит над битом не ниже, чем в релизах, — бит не тронут")
        _ffmpeg("-i", beat, "-af", head.rstrip(","), *reels.VOICE_CODEC, out)
        return out
    edges = (*SPLIT, 20000)
    for again in range(2):
        # Порог у компрессора не ниже −60 дБ, а верх голоса тише, поэтому порог стоит
        # на −20 дБ, а ключ поднимается до него. Ключ — голос, дополненный тишиной ровно
        # до длины бита (amix по первому входу): кончись голос раньше, сайдчейн оборвал
        # бы бит. Середина и ключ дополнены тишиной (ROOM_PAD): sidechaincompress закрывает
        # выход с концом любого входа и бросает то, что не дождалось пары, а бит и голос —
        # два файла, и кто кончится первым, решает планировщик ffmpeg. Полосы обрывались
        # за 0–0,2 с до конца бита, от прогона к прогону по-разному: два мастера одного кода
        # расходились в хвосте до −15 дБ, а через пересчёт порогов ниже — до −35 дБ по всему
        # треку (05.10.2026). Теперь не дождавшееся — тишина, а длину возвращает amerge:
        # бока не дополнены, и он кончает по ним.
        _ffmpeg("-i", beat, "-i", dry, "-filter_complex",
                f"[0:a]{head}asplit[b][z];[b]{MS},channelsplit[m][s];[m]{ROOM_PAD},asplit={len(depth) + 1}[m0]"
                + "".join(f"[p{b}]" for b in depth) + f";[z]volume=0,{MID},{ROOM_PAD}[zero];[1:a]{MID}[v];"
                f"[zero][v]amix=inputs=2:duration=first:normalize=0,asplit={len(depth)}" + "".join(f"[k{b}]" for b in depth) + ";"
                + "".join(f"[p{b}]bandpass=f={(edges[b - 1] * edges[b]) ** 0.5:.0f}:t=q:w=1.41,asplit[x{b}][y{b}];"
                          f"[k{b}]{_band(edges[b - 1], edges[b] if b < len(SPLIT) else 0, 2)},volume={-20 - key[b]:.2f}dB[q{b}];"
                          f"[x{b}][q{b}]sidechaincompress=threshold=0.1:ratio={ROOM_RATIO}:attack=5:release={ROOM_RELEASE[b - 1]}:"
                          f"knee=1[c{b}];[y{b}]volume=-1[n{b}];" for b in depth)
                + "[m0]" + "".join(f"[c{b}][n{b}]" for b in depth)
                + f"amix=inputs={2 * len(depth) + 1}:normalize=0[M];[M][s]amerge=inputs=2,{LR}", *reels.VOICE_CODEC, out)
        # Колокола соседних полос складываются, а детектор с быстрой атакой читает слог
        # выше среднего окна: без поправки провал выходил в 1,4–2,3 раза глубже задуманного.
        # Поэтому замер провала по окнам с голосом и один пересчёт порогов. Второй пересчёт
        # добирает задуманное (1–2 кГц: недобор 1,2 дБ → 0), но экзамен на 40 релизах против:
        # голос к биту там и так на 3,3 дБ выше релиза, с ним — на 4,5 (04.10.2026).
        done = _bands(out, f"{MID},")
        got = {b: statistics.median(under[b][i] - done[b][i] for i in sung) for b in depth}
        if not again:
            key = {b: key[b] + (got[b] - depth[b]) * ROOM_RATIO / (ROOM_RATIO - 1) for b in depth}
    print("  место голосу: " + ", ".join(f"{edges[b - 1]}–{edges[b]} Гц −{got[b]:.1f} (задумано −{depth[b]:.1f})"
                                          for b in depth) + " дБ")
    return out


def _breaths(voice: Path, words: list[float], beat: tuple[float, float], work: Path) -> tuple[Path | None, list]:
    """Вдохи перед словами words: слово задом наперёд уходит в отзвук, отзвук
    разворачивается обратно и нарастает к слову с доли за BREATH_BEATS до него.
    Возвращает шину и окна вдохов."""
    length, s, spans = beat[0], BREATH_SECONDS, []
    for word in words:
        start = _on_grid(word - BREATH_BEATS * length, beat)
        if start >= 0 and word - start >= length:
            spans.append((start, word))
    if not spans:
        return None, []
    n, out = len(spans), work / "breath.wav"
    _ffmpeg("-i", voice, "-filter_complex",
            f"anoisesrc=r={RATE}:d={s}:c=pink:seed=1[n1];anoisesrc=r={RATE}:d={s}:c=pink:seed=2[n2];"
            f"[n1][n2]amerge=inputs=2,asetnsamples=64,volume='exp(-6.9*t/{s})':eval=frame,asplit={n}"
            + "".join(f"[r{k}]" for k in range(n)) + f";[0:a]asplit={n}" + "".join(f"[v{k}]" for k in range(n)) + ";"
            + "".join(f"[v{k}]atrim=start={word:.3f}:end={word + length:.3f},asetpts=PTS-STARTPTS,areverse,"
                      f"highpass=f=300,lowpass=f=7000,apad=pad_dur={s}[i{k}];[i{k}][r{k}]afir,areverse,"
                      f"atrim=start={s - (word - start):.3f}:end={s:.3f},asetpts=PTS-STARTPTS,afade=t=in:d={word - start:.3f},"
                      f"afade=t=out:st={word - start - 0.03:.3f}:d=0.03,adelay={1000 * start:.0f}|{1000 * start:.0f}[o{k}];"
                      for k, (start, word) in enumerate(spans))
            + "".join(f"[o{k}]" for k in range(n)) + f"amix=inputs={n}:normalize=0:duration=longest[w]",
            "-map", "[w]", "-ar", RATE, *reels.VOICE_CODEC, out)
    return out, spans


def _opening(beat_file: Path, first: float, beat: tuple[float, float], work: Path) -> Path:
    """Бит до первого слова — из-под фильтра: за FILTER_BEATS долей закрывается
    до FILTER_LOW Гц за одну долю и за OPEN_BEATS долей открывается к сильной
    доле первого слова. Слово с первой секунды или свой дроп у бита (OWN_DROP) до первого
    слова или в такт после — бит как есть: у «Асапчика» бочка входит через секунду после
    первого слова, и фильтр открывался за долю до готового дропа, мимо удара."""
    length = beat[0]
    opened = _on_grid(first - 0.1, beat, math.ceil)
    sweep = opened - OPEN_BEATS * length
    if sweep < length:
        return beat_file
    shut = max(0.0, _on_grid(opened - FILTER_BEATS * length, beat))
    low, step = _envelope(beat_file, f"atrim=start={shut:.3f}:end={opened + 4 * length:.3f},lowpass=f=150,lowpass=f=150,"), round(2 * length * ENV_RATE)
    halves = [statistics.fmean(low[i:i + step]) for i in range(0, len(low), step)]
    if drop := next((k for k in range(1, len(halves)) if halves[k] - min(halves[:k]) >= OWN_DROP), None):
        print(f"  у бита свой дроп на {shut + drop * 2 * length:.1f} с — без фильтра до первого слова")
        return beat_file
    closed = shut + length if shut else 0.0
    steps = []
    for n in range(int((opened - shut) / 0.02)):
        t = shut + n * 0.02
        low = (FILTER_LOW * (20000 / FILTER_LOW) ** ((t - sweep) / (opened - sweep)) if t >= sweep
               else 20000 * (FILTER_LOW / 20000) ** ((t - shut) / length) if t < closed else FILTER_LOW)
        steps.append(f"{n * 0.02:.2f} lowpass@open f {low:.0f};")
    (work / "opening.cmd").write_text("\n".join(steps))
    out, parts = work / "beat-open.wav", [f"atrim=start={shut:.4f}:end={opened:.4f},asetpts=PTS-STARTPTS,"
                                          f"asendcmd=f='{work / 'opening.cmd'}',lowpass@open=f={20000 if shut else FILTER_LOW}:t=q:w=1.2",
                                          f"atrim=start={opened:.4f},asetpts=PTS-STARTPTS"]
    if shut:
        parts.insert(0, f"atrim=end={shut:.4f}")
    _ffmpeg("-i", beat_file, "-filter_complex",
            f"[0:a]asplit={len(parts)}{''.join(f'[i{n}]' for n in range(len(parts)))};"
            + "".join(f"[i{n}]{part}[o{n}];" for n, part in enumerate(parts))
            + "".join(f"[o{n}]" for n in range(len(parts))) + f"concat=n={len(parts)}:v=0:a=1",
            *reels.VOICE_CODEC, out)
    return out


# Где голос встаёт на бит. Оба файла сведение кладёт от нуля, и вокал, выгруженный
# не с начала проекта, уезжает: 26.09 у вокала на 34 с первое слово было на 2,8 с,
# а бас в бите на 2:33 входил на 13 с — голос звучал на вступлении, и человек
# написал, что он «не попадает в дроп». Где голос стоял в проекте, по звуку не узнать:
# читать на вступлении тоже можно. Поэтому само сведение голос не двигает, а называет
# дроп и даёт его кнопкой (DROP_NOTE), и место голоса можно сказать словами (ручка at).
def drops(beat: Path, rhythm: tuple[float, float], sign: int = 1) -> list[float]:
    """Дропы бита: доли, где низ до 120 Гц (бочка и бас) за такт после становится
    громче такта до на OWN_DROP дБ; sign −1 — тише: бочка и бас ушли, бит замолк.
    Порог громкости громкого из двух тактов — на 20 дБ ниже громкой части, а не на 10:
    в первом такте после дропа у 808 бывают провалы."""
    _, trace = reels.meter(beat, "lowpass=f=120,")
    level = [m for _, m, _ in trace]
    n = max(1, round(4 * rhythm[0] / (trace[1][0] - trace[0][0])))
    loud = sorted(level)[int(0.9 * len(level))]
    rise = {i: sign * (after - before) for i in range(n, len(level) - n)
            if max(before := statistics.fmean(level[i - n:i]), after := statistics.fmean(level[i:i + n])) >= loud - 20}
    found = []
    for i, r in rise.items():
        if r >= OWN_DROP and r >= max(rise.get(j, r) for j in range(i - n, i + n + 1)) and (not found or i - found[-1] > n):
            found.append(i)
    # Громкость M меряется окном 0,4 с: край дропа — на полокна раньше.
    return [round(_on_grid(trace[i][0] - 0.2, rhythm), 2) for i in found]


def first_word(vocal: Path) -> float:
    """Секунда первого слова в файле голоса."""
    lines = _lines(_envelope(vocal, f"{FORMAT},"))
    return round(lines[0][0], 2) if lines else 0.0


def _moved(path: Path, shift: float, dest: Path) -> Path:
    """Дорожка голоса на shift секунд позже (тишиной в начале) или раньше (срезом начала)."""
    _ffmpeg("-i", path, "-af", f"adelay=delays={1000 * shift:.0f}:all=1" if shift > 0
            else f"atrim=start={-shift:.3f},asetpts=PTS-STARTPTS", *reels.VOICE_CODEC, dest)
    return dest


def _spread(moments: list[tuple[float, float]], gap: float, limit: int = 99) -> list[float]:
    """Моменты (вес, секунда) — самые весомые первыми, не ближе gap секунд друг
    к другу, не больше limit."""
    picked = []
    for _, t in sorted(moments, reverse=True):
        if len(picked) < limit and all(abs(t - c) >= gap for c in picked):
            picked.append(t)
    return sorted(picked)


def _throws(voice: Path, throws: list[tuple[float, float, float]], length: float, work: Path) -> Path | None:
    """Броски: слово от его начала a до конца фразы e — в дилей в темп так, что первый
    повтор (восьмая справа) встаёт на удар бочки k; повторы приседают под голосом."""
    if not throws:
        return None
    n, send, out = len(throws), work / "throw-send.wav", work / "throws.wav"
    _ffmpeg("-i", voice, "-filter_complex", f"[0:a]asplit={n}" + "".join(f"[v{j}]" for j in range(n)) + ";"
            + "".join(f"[v{j}]atrim=start={a - 0.005:.3f}:end={e + 0.03:.3f},asetpts=PTS-STARTPTS,afade=t=in:d=0.005,"
                      f"afade=t=out:st={e - a + 0.025:.3f}:d=0.01,adelay={1000 * (k - length / 2 - 0.005):.0f}:all=1[o{j}];"
                      for j, (a, e, k) in enumerate(throws))
            + "".join(f"[o{j}]" for j in range(n)) + f"amix=inputs={n}:normalize=0,apad=whole_dur={clips.probe_seconds(voice):.2f}",
            *reels.VOICE_CODEC, send)
    _ffmpeg("-i", send, "-i", voice, "-filter_complex",
            _tempo_delay(length, loudness(voice)[0], "[1:a]", clips.probe_seconds(send)),
            "-map", "[w]", "-ar", RATE, *reels.VOICE_CODEC, out)
    return out


# Остановка бита, где молчит и голос. Бит перед входом следующей части замолкает сам, а в файле
# голоса между частями — цифровая тишина: в заказе ручного сведения 04.10.2026 в готовом треке
# выходили провалы до −34…−49 дБ длиной около секунды, владелец: «ничего не слышно, как будто
# срезаны паузы». Его правило — внутри трека нет окна HOLD_WINDOW тише −26 дБ при мастере на
# −11 LUFS, на 15 дБ тише громкого; в сумме до мастера это HOLD_BELOW к середине окон: мастер
# громкое сжимает на 2–3 дБ, а тихое только поднимает. Меряется сумма, а не один бит: хвост
# отзвука, эдлиб или бросок провал уже могли закрыть. И сам бит в этом окне должен замолкнуть —
# стать на HOLD_BELOW тише, чем под последней фразой: тихое вступление, где голос идёт с паузами
# поверх еле слышной подложки, — не остановка. Нет такого окна в паузе голоса — в трек
# не добавляется ничего.
# Лечится, как в ручной версии: эхо последнего слова держится до входа следующей части. Слово —
# последняя восьмая фразы — повторяется встык каждую восьмую от стены к стене (HOLD_PAN), шина
# эха — на HOLD_DB LU к голосу, как броски. В ручной версии повтор гас на 1,5 дБ, а конец паузы
# закрывал разворот первого слова; разворота у бота нет, поэтому эхо гаснет медленнее —
# на HOLD_FALL дБ в секунду.
# Пауза короче HOLD_PAUSE[0] — рисунок артиста, а не дыра. Длиннее HOLD_PAUSE[1] эхом не закрыть:
# слово, повторенное десяток раз, — заевшая пластинка, и к концу паузы оно всё равно ушло бы
# под порог. Такая остановка и остановка до первого слова (повторять нечего) остаются как были.
HOLD_WINDOW = 0.25
HOLD_BELOW = 17.0
HOLD_PAUSE = (1.0, 4.0)
HOLD_DB = -8.0
HOLD_FALL = -1.0
HOLD_PAN = (0.85, 0.45)


def _hold(total: Path, voice: Path, beat: Path, rhythm: tuple[float, float] | None, work: Path, echo: float = 0.0) -> list[float]:
    """Эхо последнего слова в остановках бита (HOLD_*): сумма total переписывается с ним.
    Возвращает секунды, где слово кончилось; остановок нет — пусто, и total не тронут."""
    n, down = round(HOLD_WINDOW * ENV_RATE), 10 ** (-HOLD_BELOW / 20)

    def windows(path: Path) -> list[float]:
        level = [10 ** (db / 20) for db in _envelope(path)]
        return [statistics.fmean(level[i:i + n]) for i in range(len(level) - n + 1)]

    track, played, stops = windows(total), windows(beat), []
    floor, phrases = statistics.median(track) * down, _lines(_envelope(voice), PHRASE_RANGE, PHRASE_PAUSE)
    for (start, end), (nxt, _) in zip(phrases, phrases[1:]):
        a, b = round(end * ENV_RATE), round((nxt - HOLD_WINDOW) * ENV_RATE) + 1
        under = statistics.fmean(played[round(start * ENV_RATE):a] or [0.0]) * down
        if HOLD_PAUSE[0] <= nxt - end <= HOLD_PAUSE[1] and any(t < floor and p < under for t, p in zip(track[a:b], played[a:b])):
            stops.append((end, nxt))
    if not stops:
        return []
    step, graph = (rhythm or grid(beat))[0] / 2, f"[0:a]asplit={len(stops)}" + "".join(f"[v{j}]" for j in range(len(stops))) + ";"
    for j, (end, nxt) in enumerate(stops):
        start, taps = max(0.0, end - step), range(1, math.ceil((nxt - end) / step) + 1)
        graph += (f"[v{j}]atrim=start={start:.3f}:end={end:.3f},asetpts=PTS-STARTPTS,highpass=f=200,lowpass=f=5000,"
                  f"pan=mono|c0=0.5*c0+0.5*c1,afade=t=in:d=0.05,afade=t=out:st={end - start - 0.01:.3f}:d=0.01,"
                  f"apad=pad_dur={nxt - end:.3f},asplit[a{j}][b{j}];"
                  + "".join(f"[{side}{j}]aecho=in_gain=0:out_gain=1:delays=" + "|".join(f"{1000 * step * k:.0f}" for k in taps)
                            + ":decays=" + "|".join(f"{HOLD_PAN[(k + odd) % 2] * 10 ** (HOLD_FALL * step * (k - 1) / 20):.3f}" for k in taps)
                            + f"[{side}{side}{j}];" for odd, side in enumerate("ab"))
                  + f"[aa{j}][bb{j}]amerge=inputs=2,atrim=end={nxt - start:.3f},afade=t=out:st={nxt - start - 0.1:.3f}:d=0.1,"
                    f"adelay={1000 * start:.0f}:all=1[o{j}];")
    held = work / "hold.wav"
    _ffmpeg("-i", voice, "-filter_complex", graph + "".join(f"[o{j}]" for j in range(len(stops)))
            + f"amix=inputs={len(stops)}:normalize=0:duration=longest[w]", "-map", "[w]", "-ar", RATE, *reels.VOICE_CODEC, held)
    _sum([(total, 0.0), (held, loudness(voice)[0] + HOLD_DB + echo - _quiet(held))], work / "sum-hold.wav").replace(total)
    print("  остановки бита, где молчит голос: эхо последнего слова до входа следующей части, с "
          + ", ".join(f"{end:.1f}" for end, _ in stops) + " с")
    return [end for end, _ in stops]


def _phone(voice: Path, spans: list[tuple[float, float]], work: Path) -> Path:
    """Голос через телефон (PHONE) на отрезках spans, той же громкости; края — по 10 мс."""
    on = [(0.0, -120.0)] + [p for a, b in spans for p in ((a - 0.01, -120.0), (a, 0.0), (b - 0.01, 0.0), (b, -120.0))]
    seconds, lift = clips.probe_seconds(voice) + 1, loudness(voice)[0] - loudness(voice, PHONE + ",")[0]
    return _sum([(_apply(voice, _gain_track([(t, -120.0 - g) for t, g in on], seconds, work / "open.wav"),
                         work / f"{voice.stem}-open.wav"), 0.0),
                 (_apply(voice, _gain_track(on, seconds, work / "phone.wav"), work / f"{voice.stem}-phone.wav",
                         f"{PHONE},volume={lift:.2f}dB"), 0.0)], work / f"{voice.stem}-tel.wav")


def _audible(bed: Path, parts: list[tuple[str, Path, float, list, list]]) -> str:
    """Слышимость приёмов: громкость каждого в его окнах к биту в окнах ref, LU —
    энергетическое среднее окон EBU R128 M (0,4 с), чьи середины лежат в окне.
    Окна, где бит молчит (вдох в вступлении без бита), не в счёт: там не с чем сравнивать."""
    def level(trace, spans) -> float:
        hits = [10 ** (m / 10) for t, m, _ in trace if any(a <= t - 0.2 <= b for a, b in spans)]
        return 10 * math.log10(statistics.fmean(hits)) if hits else -120.0
    whole, under = reels.meter(bed)
    report = []
    for name, path, gain, spans, ref in parts:
        pairs = [(span, back) for span, back in zip(spans, ref) if level(under, [back]) >= whole - 20]
        if pairs:
            spans, ref = zip(*pairs)
            report.append(f"{name} {level(reels.meter(path)[1], spans) + gain - level(under, ref):+.0f}")
    return ", ".join(report) + " LU к биту"


def _stop_at(beat_file: Path, lines: list[tuple[float, float]], beat: tuple[float, float]) -> float | None:
    """Доля для остановки плёнки — в конце последнего куска, где бит играет
    в полную силу хотя бы STOP_BEATS долей подряд, и после последней строки.
    Одиночный финальный удар после тихой концовки куском не считается:
    в Little Chicago's Finest плёнка тормозила именно его."""
    _, trace = reels.meter(beat_file)
    loud = sorted(m for _, m, _ in trace)[int(len(trace) * 0.9)] - 6
    runs = []
    for t, m, _ in trace:
        if m < loud:
            continue
        if runs and t - runs[-1][1] < 0.15:
            runs[-1][1] = t
        else:
            runs.append([t, t])
    full = [end - 0.2 for start, end in runs if end - start >= STOP_BEATS * beat[0]]
    at = _on_grid(full[-1] - STOP_BEATS * beat[0] / 2, beat, math.floor) if full else 0.0
    return at if lines and at > lines[-1][1] else None


def _tape_stop(master: Path, at: float, length: float, work: Path) -> None:
    """Остановка плёнки с доли at: скорость падает до нуля за STOP_BEATS долей, дальше
    трек кончается. ffmpeg меняет скорость только на весь файл, поэтому хвост
    читается заново с плавающей скоростью здесь же."""
    span = STOP_BEATS * length
    raw = subprocess.run([clips.ffmpeg(), "-v", "error", "-ss", f"{at:.4f}", "-t", f"{span:.4f}", "-i", str(master),
                          "-f", "f32le", "-ac", "2", "-"], capture_output=True, check=True).stdout
    x, tail, pos, total = array.array("f", raw), array.array("f"), 0.0, int(span * RATE)
    for n in range(total):
        i = int(pos)
        if 2 * i + 3 >= len(x):
            break
        frac = pos - i
        tail.extend((x[2 * i] * (1 - frac) + x[2 * i + 2] * frac, x[2 * i + 1] * (1 - frac) + x[2 * i + 3] * frac))
        pos += 1 - n / total
    (work / "stop.raw").write_bytes(tail.tobytes())
    stopped = work / "stopped.wav"
    _ffmpeg("-i", master, "-f", "f32le", "-ar", RATE, "-ac", 2, "-i", work / "stop.raw", "-filter_complex",
            f"[0:a]atrim=end={at:.4f}[a];[1:a]afade=t=out:st={len(tail) / 2 / RATE - 0.02:.4f}:d=0.02[b];"
            "[a][b]concat=n=2:v=0:a=1", "-c:a", "pcm_s24le", stopped)
    stopped.replace(master)


def _glue(total: Path) -> str:
    """Склейка шины (GLUE) с порогом по замеру: сжатие GLUE дБ по EBU R128."""
    level = loudness(total)[0]
    if level <= -69:
        # −70 — «не намерил»: сжимать нечего, а порог ниже −60 дБ acompressor не берёт.
        print(f"  склейка шины: сумма {level:.1f} LUFS — без склейки")
        return ""
    threshold, drop = level - 2 * GLUE, 0.0
    for _ in range(4):
        # Пределы порога у acompressor — от −60 дБ до 0.
        chain = f"acompressor=threshold={min(1.0, max(0.00098, 10 ** (threshold / 20))):.5f}:ratio=2:attack=30:release=200,"
        drop = level - loudness(total, chain)[0]
        if abs(drop - GLUE) < 0.2:
            break
        threshold -= 2 * (GLUE - drop)
    print(f"  склейка шины: 2:1, сжатие {drop:.1f} дБ")
    return chain


def _coded(master: Path) -> float:
    """Истинный пик master после MP3 — того же кодека, каким трек уходит человеку (_send), dBTP."""
    mp3 = master.with_suffix(".peak.mp3")
    _ffmpeg("-i", master, *MP3, mp3)
    peak = loudness(mp3)[1]
    mp3.unlink()
    return peak


def _master(total: Path, glue: str, master: Path, target: float = MASTER_LUFS) -> tuple[float, float, float]:
    """Мастер: низ в моно, склейка шины, клиппер и ограничитель до target LUFS —
    в master. Возвращает громкость, истинный пик и подъём.

    Клиппер и ограничитель съедают часть громкости, поэтому подъём подбирается
    замером. Пик волны лежит между отсчётами и на 44,1 кГц выходит до дБ выше
    порога, поэтому оба работают на учетверённой частоте. Клиппер упирается в ноль,
    и сигнал к нему подводится так, чтобы ноль пришёлся на CLIP дБ над порогом.

    Потолок держит не WAV, а готовый MP3: человеку и в канал уходит он, а кодек
    поднимает пик. Экзамен 09.10.2026, 80 сведений: MP3 320 выше своего WAV на 0,1 дБ
    по медиане (квартили 0,1…0,2), у 30 из 80 — выше потолка, худший −1,6 dBTP;
    на ручном заказе потолок WAV ради этого опускали руками. Пик здесь — больший
    из двух, и порог ограничителя сходится уже к нему: выше потолка — ни одного из 80,
    громкость та же. Цена — WAV таких треков (31 из 80) сжат на 0,1–0,5 дБ сильнее («пик к громкости
    без MP3» из сырого −0,90 → −1,05); после MP3, как у эталонов, удар тот же."""
    push, limit = target - loudness(total, glue)[0], CEILING - 0.3
    for _ in range(6):
        _ffmpeg("-i", total, "-af",
                f"{LOW_MONO},{glue}volume={push - limit - CLIP:.2f}dB,aresample={4 * RATE},{CLIPPER},"
                f"volume={limit + CLIP:.2f}dB,"
                f"alimiter=limit={10 ** (limit / 20):.4f}:attack=5:release=150:asc=1:level=0:latency=1,"
                f"aresample={RATE}",
                "-c:a", "pcm_s24le", master)
        level, peak = loudness(master)
        peak = max(peak, _coded(master))
        if abs(level - target) < 0.3 and peak <= CEILING:
            break
        push += target - level
        # Ровно на превышение порог сходится к потолку снизу бесконечно — с запасом 0,1 дБ.
        limit -= peak - CEILING + 0.1 if peak > CEILING else 0.0
    return level, peak, push


def _sides(path: Path) -> float:
    """Стороны к середине выше LIKE_BAND, дБ: чем больше, тем шире."""
    mid, side = _channels(path, f"{FORMAT},{LIKE_BAND}{MS},")[:2]
    return side - mid


def _shape(total: Path, gains: dict[int, float], wide: float, work: Path) -> Path:
    """Сумма сведения с колоколами gains и сторонами громче на wide дБ — в work/like.wav."""
    k, matched = 10 ** (wide / 20), work / "like.wav"
    _ffmpeg("-i", total, "-af", f"{_bells(gains)}pan=stereo|c0={(1 + k) / 2:.4f}*c0+{(1 - k) / 2:.4f}*c1"
            f"|c1={(1 - k) / 2:.4f}*c0+{(1 + k) / 2:.4f}*c1", *reels.VOICE_CODEC, matched)
    return matched


VOICES = "voices.wav"  # голос сведения без бита, в out/work
TOTAL = "sum.wav"  # голос с битом до мастера, там же: к ней контроль меряет голос


def mix(vocal: Path, beat: Path, out: Path, style: str = "чисто", design: bool = False,
        voice: float = 0.0, echo: float = 0.0, parts: list[tuple[str, Path]] = (), like: Path | None = None,
        lost: list[str] | None = None, held: list[float] | None = None,
        said: tuple[str, list[int]] | None = None, soft: str = "", loose: list[str] | None = None) -> Path:
    """Сведение в out/skleyka.wav, промежуточное — в out/work.

    parts — дорожки по отдельности, [(роль, файл)]: даблы, бэки и эдлибы встают вокруг
    ведущего vocal (voices); пришли барабаны или бас — место голосу делается только
    в остальном бите, а удары бочки для саунд-дизайна ищутся в них. beat — весь бит
    вместе, по нему меряются темп, громкость и дропы.

    Ручки бота: voice — голос к биту, дБ («голос громче / тише» — по ±2): сдвигает
    и баланс, и цель райдера, иначе в местах, где бит перекрывал голос, райдер
    съел бы поправку; echo — доля отзвука, дилея и бросков к своей, дБ («эха
    больше / меньше» — по ±4); дабл не эхо, его не трогает. like — превью трека, к которому
    подтянуть тембр, ширину и громкость («как у <артиста>», _like). lost — сюда роли
    частей, которые в трек не вошли: обработка их испортила; held — сюда секунды остановок
    бита, где придержано эхо последнего слова (_hold). said — тональность со слов человека
    или автора бита (_said): к её нотам тянет автотюн; soft — его мягкость (SOFT); loose — сюда
    отметка, что тональность неизвестна и тюн шёл по двенадцати полутонам."""
    look, work = STYLES[style], out / "work"
    work.mkdir(parents=True, exist_ok=True)
    project = abs(clips.probe_seconds(vocal) - clips.probe_seconds(beat)) <= SAME_PROJECT
    print(f"  стиль «{style}»: {look['about']}" + (", саунд-дизайн" if design else "")
          + (f", голос {voice:+g} дБ" if voice else "") + (f", эхо {echo:+g} дБ" if echo else ""))

    clean = f"{FORMAT},{_center(vocal)}{HIGHPASS}"
    if tune := look.get("autotune") and _autotune(beat, said, soft, loose):
        clean += f",{tune}"
    squeezed, dry, raw = work / "vocal-comp.wav", work / "vocal.wav", loudness(vocal, clean + ",")[0]
    _squeeze(vocal, f"{clean},volume={VOCAL_LUFS - raw:.2f}dB", squeezed, f",{DENSE}" if look.get("dense") else "")
    lines = _lines(_envelope(squeezed))
    deess = _deesser(squeezed)
    _ffmpeg("-i", squeezed, "-af", ("" if project else _equalizer(squeezed, lines, work, deess)) + deess + look.get("color", "anull"),
            *reels.VOICE_CODEC, dry)
    sung = loudness(dry)[0]

    width = stereo(beat, LOW_BAND)[0]
    flip = "pan=stereo|c0=c0|c1=-1*c1," if width < 0 else ""
    head = f"{FORMAT},{flip}"
    print(f"  бит: связь каналов ниже 120 Гц {width:+.2f}" + (", один канал перевёрнут" if flip else ""))
    balance = VOCAL_OVER_BEAT
    if project:
        balance = min(max(raw - loudness(beat, head)[0], BALANCE_RANGE[0]), BALANCE_RANGE[1])
        print(f"  голос и бит из одного проекта: голос к биту {balance:+.1f} дБ и тембр — как у артиста")
    # Барабаны и бас пришли отдельно — место голосу только в остальном бите.
    drums = [path for part, path in parts if part in ("барабаны", "бас")]
    music = [path for part, path in parts if part in ("бит", "музыка")] if drums else [beat]
    kit = _sum([(path, 0.0) for path in drums], work / "kit.wav", head.rstrip(",")) if drums else None
    room = None
    if music:
        whole = music[0] if len(music) == 1 else _sum([(path, 0.0) for path in music], work / "music.wav")
        room = _room(whole, dry, head, loudness(beat, head)[0] + balance + voice - sung, lines, work)
    ducked = _sum([(room, 0.0), (kit, 0.0)], work / "beat-parts.wav") if room and kit else room or kit
    under = loudness(ducked)[0]
    ridden = _ride(dry, ducked, under + balance + voice - sung, balance + voice + RIDE_TARGET, work)
    level = loudness(ridden)[0]
    placed = voices([(part, path) for part, path in parts if part in PARTS], level, work / "ride.wav", work, tune or "", project,
                    sum(b - a for a, b in lines))

    adlibs = [(path, gain) for path, gain, part in placed if part == "эдлиб"]
    rhythm = grid(beat) if design or adlibs or look.get("delay", ("",))[0] == "в темп" else None
    if rhythm:
        print(f"  темп {60 / rhythm[0]:.1f} ударов в минуту, сильная доля {rhythm[1]:.2f} с")
    sends = []
    if "reverb" in look:
        seconds, share = look["reverb"]
        sends.append(("reverb", _reverb(seconds), share))
    if "delay" in look:
        kind, share = look["delay"]
        sends.append(("delay", reels.DELAY if kind == "коротко" else _tempo_delay(rhythm[0], level), share))
    if look.get("double") and stereo(dry)[0] > 0.98:
        sends.append(("double", DOUBLE, DOUBLE_SHARE))
    wets = []  # (шина, громкость в сведении по EBU R128)
    for name, graph, share in sends:
        wet = work / f"{name}.wav"
        _ffmpeg("-i", ridden, "-filter_complex", graph, "-map", "[w]", "-ar", RATE, *reels.VOICE_CODEC, wet)
        wets.append((wet, level + 20 * math.log10(share) + (0.0 if name == "double" else echo)))
    # Свой отзвук бэков и эдлибов: посыл каждой части — на её громкости в сумме плюс reverb,
    # и шина отзвука выходит той же громкостью, что посыл.
    if going := [(path, gain + PARTS[part]["reverb"]) for path, gain, part in placed if PARTS[part]["reverb"] is not None]:
        send, wet = _sum(going, work / "send-parts.wav"), work / "parts-room.wav"
        _ffmpeg("-i", send, "-filter_complex", _reverb(PARTS_ROOM), "-map", "[w]", "-ar", RATE, *reels.VOICE_CODEC, wet)
        wets.append((wet, loudness(send)[0] + echo))
    # Эхо эдлибов — своё, в темп, приседает под ведущим: повторы — в его паузах.
    for n, (path, gain) in enumerate(adlibs):
        wet = work / f"adlib-echo{n}.wav"
        _ffmpeg("-i", path, "-i", ridden, "-filter_complex", _tempo_delay(rhythm[0], level, "[1:a]", clips.probe_seconds(path)),
                "-map", "[w]", "-ar", RATE, *reels.VOICE_CODEC, wet)
        wets.append((wet, loudness(path)[0] + gain + ADLIB_ECHO + echo))
    # Голос и его шины до трюков саунд-дизайна (телефон меняет и сам голос).
    own, plain = len(wets), [(ridden, 0.0), *((path, gain) for path, gain, _ in placed)]
    bed, tricks = ducked, []
    if design and lines:
        length, first = rhythm[0], lines[0][0]
        heard = _envelope(ridden)
        phrases = _lines(heard, PHRASE_RANGE, PHRASE_PAUSE)
        # Удар бочки — доля сетки (grid стоит на бочке), где низ играет в полную силу.
        # До 30.09 доля подтягивалась к ближайшему росту низа, а он бывает нотой 808:
        # на «Асапчике» эффекты уходили с удара на 0,2 с. Замер по барабанам, отделённым
        # demucs, на пяти битах: в 20 мс от удара бочки 226 долей сетки из 296, после
        # подтяжки — 108, из долей с громким низом — 223 из 254.
        low = _envelope(kit or beat, "lowpass=f=120,lowpass=f=120,")
        loud = sorted(low)[int(0.9 * len(low))] - 15
        kicks = [t for n in range(int(len(low) / ENV_RATE / length)) if max(
            low[max(0, round((t := rhythm[1] % length + n * length) * ENV_RATE) - 3):round(t * ENV_RATE) + 4]) >= loud]
        ins = drops(beat, rhythm)
        changes = ins + drops(beat, rhythm, -1)
        drop = next((c for c in ins if c > first + length), None)
        # Дроп меряется тактами и бывает на долю раньше удара (у одного из релизов бас
        # вошёл на долю раньше бочки): голос открывается на первом ударе от доли до дропа.
        drop = drop and next((t for t in kicks if t > drop - 1.5 * length), drop)
        before = [a for a, _ in phrases if drop and drop - 4 * length <= a < drop][-PHONE_LINES:]
        phone = [(before[0] - 0.05, drop)] if before else []
        if phone:
            ridden = _phone(ridden, phone, work)
            heard = _envelope(ridden)  # бросок режется из голоса в телефоне
            placed = [(_phone(path, phone, work), gain, part) for path, gain, part in placed]
        picks = {}
        for (_, end), (nxt, _) in zip(phrases, [*phrases[1:], (math.inf, 0.0)]):
            if kick := next((t for t in kicks if end <= t < min(nxt, end + 4 * length)), None):
                # Удар слова — самый резкий рост уровня (по окнам 10 мс через одно, начался
                # в окне перед ним) там, где слово уже в 10 дБ от своего пика: гласная,
                # а не согласная перед ней — в такт звучит она.
                span = range(max(2, round((end - THROW_WORD) * ENV_RATE)), round(end * ENV_RATE) - 5)
                top = max(heard[i] for i in span)
                word = max((i for i in span if heard[i] >= top - 10), key=lambda i: heard[i] - heard[i - 2])
                picks[end] = ((word - 0.5) / ENV_RATE, kick, nxt - end + 99 * any(0 <= c - end <= 4 * length for c in changes))
        throws = [(picks[e][0], e, picks[e][1])
                  for e in _spread([(w, e) for e, (_, _, w) in picks.items()], THROW_BARS * 4 * length, THROWS)]
        print(f"  саунд-дизайн: первое слово {first:.2f} с; смены в бите " + (", ".join(f"{c:.1f}" for c in sorted(changes)) or "—")
              + " с; броски на удар " + (", ".join(f"{k:.2f}" for _, _, k in throws) or "—")
              + (f" с; телефон {phone[0][0]:.1f}–{phone[0][1]:.2f} с" if phone else " с"))
        bed = _opening(ducked, first, rhythm, work)
        breath, spans = _breaths(ridden, [first], rhythm, work)
        hits = [(k, k + 3 * length) for _, _, k in throws]
        tricks = [("вдохи", breath, level + BREATH_DB, spans, spans),
                  ("броски", _throws(ridden, throws, length, work), level + THROW_DB + echo, hits, hits)]
        wets += [(path, target) for _, path, target, _, _ in tricks if path]
    gains = {wet: target - _quiet(wet) for wet, target in wets}
    # Одна точка NaN или бесконечности — и фильтры мастера портят трек от неё до конца
    # (так 29–30.09 vibrato испортил бэк, DOUBLE). Испорченная часть или шина в сумму
    # не идёт, человеку об этом скажут (lost); голос и бит заменить нечем — это сбой.
    if _broken(ridden) or _broken(bed):
        raise clips.ClipError("в голосе или бите после обработки NaN или бесконечность")
    spoiled = [(part, path) for path, _, part in placed if _broken(path)] + [(wet.stem, wet) for wet in gains if _broken(wet)]
    if spoiled:
        print("  NaN или бесконечность, в сумму не идёт: " + ", ".join(name for name, _ in spoiled))
        bad = {path for _, path in spoiled}
        if lost is not None:
            lost += [part for path, _, part in placed if path in bad]
        keep = [path not in bad for path, _, _ in placed]
        placed = [item for item, ok in zip(placed, keep) if ok]
        plain = [plain[0], *(item for item, ok in zip(plain[1:], keep) if ok)]
        gains = {wet: gain for wet, gain in gains.items() if wet not in bad}
    total = _sum([(ridden, 0.0), (bed, 0.0), *((path, gain) for path, gain, _ in placed), *gains.items()], work / TOTAL)
    # Голос без бита — звук приложения «🎚 Двигать голос»: сырой голос там тонул под битом.
    # Трюки саунд-дизайна привязаны к месту голоса и к биту — при сдвиге они были бы не там.
    _sum([*plain, *((wet, gains[wet]) for wet, _ in wets[:own] if wet in gains)], work / VOICES)
    try:
        stops = _hold(total, ridden, beat, rhythm, work, echo)
    except Exception as exc:  # noqa: BLE001 — без эха в остановке трек всё равно уходит, каким был
        stops = []
        print(f"  эхо в остановках бита не собралось: {type(exc).__name__}")
    if held is not None:
        held += stops
    if tricks:
        print("  слышно: " + _audible(bed, [(name, path, gains.get(path, 0.0), spans, ref)
                                            for name, path, _, spans, ref in tricks if path and spans]))

    # «Как у <артиста>»: сверяется готовый мастер, а не сумма до него — клиппер
    # и ограничитель возвращали половину поправки, — и колокол в октаву недобирает
    # до своей середины, поэтому поправка доводится за LIKE_PASSES проходов мастера.
    master, target, gains, wide = out / "skleyka.wav", MASTER_LUFS, dict.fromkeys(TONE, 0.0), 0.0
    if like:
        theirs, their_sides = tone(like, FORMAT), _sides(like)
        target = max(LIKE_LUFS[0], min(LIKE_LUFS[1], loudness(like)[0]))
    for attempt in range(LIKE_PASSES + 1 if like else 1):
        source = _shape(total, gains, wide, work) if attempt else total
        level, peak, push = _master(source, _glue(source), master, target)
        if not like:
            break
        ours, miss_sides = tone(master, FORMAT), their_sides - _sides(master)
        miss = {f: theirs[f] - ours[f] for f in TONE}
        print(f"  к референсу, проход {attempt}: тембр отходит на {statistics.fmean(map(abs, miss.values())):.1f} дБ "
              f"в среднем, стороны — на {miss_sides:+.1f}")
        step = ({f: round(max(-LIKE_TONE, min(LIKE_TONE, gains[f] + miss[f])), 1) for f in TONE},
                round(max(-LIKE_WIDTH, min(LIKE_WIDTH, wide + miss_sides)), 1))
        if attempt == LIKE_PASSES or max(abs(step[1] - wide), *(abs(step[0][f] - gains[f]) for f in TONE)) < 0.5:
            break
        gains, wide = step
    if like:
        print("  как у референса: тембр " + (", ".join(f"{f} Гц {g:+.1f}" for f, g in gains.items() if g) or "как был")
              + f"; стороны {wide:+.1f} дБ; громкость {target:.1f} LUFS")
    if design and lines and (at := _stop_at(ducked, lines, rhythm)) is not None:
        _tape_stop(master, at, rhythm[0], work)
        print(f"  остановка плёнки с {at:.2f} с")
    corr, loss = stereo(master)
    print(f"  мастер {level:.1f} LUFS, пик {peak:.1f} dBTP, подъём {push:+.1f} дБ; "
          f"корреляция каналов {corr:+.2f}, в моно тише на {loss:.1f} LU")
    return master


def compare(vocal: Path, beat: Path, master: Path, out: Path) -> tuple[Path, Path]:
    """ДО и ПОСЛЕ одной громкости по LUFS: out/do.mp3 — простая сумма, out/posle.mp3 — сведение.

    Уровень — громкость сведения, а если простая сумма там уже упирается в пик,
    то ниже, где она ещё не клиппует: ДО без ограничителя, иначе сравнивался бы
    ограничитель, а не сведение.
    """
    plain = out / "work" / "plain.wav"
    _ffmpeg("-i", vocal, "-i", beat, "-filter_complex",
            f"[0:a]{FORMAT}[v];[1:a]{FORMAT}[b];[v][b]amix=inputs=2:duration=longest:normalize=0",
            *reels.VOICE_CODEC, plain)
    (raw, peak), glued = loudness(plain), loudness(master)[0]
    level = min(glued, raw + CEILING - peak)
    pair = out / "do.mp3", out / "posle.mp3"
    for source, now, dest in ((plain, raw, pair[0]), (master, glued, pair[1])):
        _ffmpeg("-i", source, "-af", f"volume={level - now:.2f}dB", *MP3, dest)
    print(f"  ДО и ПОСЛЕ на {level:.1f} LUFS; " + ", ".join(
        f"{name}: корреляция {corr:+.2f}, в моно −{loss:.1f} LU"
        for name, (corr, loss) in (("ДО", stereo(plain)), ("ПОСЛЕ", stereo(master)))))
    return pair


# ─────────────────────────── части голоса ───────────────────────────
#
# Даблы, бэки и эдлибы, присланные отдельно, не сваливаются в главный голос: у каждой
# роли у инженеров своё место (docs/research/2026-09-22/zvukorezhissura.md, раздел 6).
# Даблы тише и суше ведущего, низа срезано больше, эсок нет (KRUG, Podlesny Twins), и ведёт
# их тот же райдер — они идут за словами ведущего; два и больше — по краям на одном уровне
# (Сениор), один — в центре под ведущим. Бэки — очень широко (Goldberg) и дальше, в отзвук;
# эдлибы — по краям и в эхо: им можно меньше внятности и больше эффектов (Hoffman, Waves).
# Цифр громкости у инженеров нет, только «достаточно тихо» (KRUG): дБ к ведущему — выбор
# сведения. Одна дорожка бэков расходится в стороны расширителем Сениора (DOUBLE)
# без центра — центр остаётся ведущему (Heldens).
#
# Пространство. У ведущего отзвук и дилей — отдельные шины, подмешанные тихо: голос
# остаётся сухим и чётким (Firkins — 15 % мокрого, Schaeffer, Joshua). Бэки и эдлибы,
# наоборот, растворяются в своём отзвуке (владелец 22.09.2026: «на бэке оставляю дилей
# и реверб на той же шине… чтобы они растворялись»; Bainz — броски «100‑percent wet»):
# reverb — громкость их общего отзвука PARTS_ROOM к ним самим, дБ, мимо стиля ведущего;
# None — сухо, как даблы у KRUG. Ручка «эха» двигает и его. До 01.10.2026 было −14 у бэков
# и −16 у эдлибов; владелец, послушав своё сведение: «бэки, эйры я бы больше в пространство
# закинул» — поднято на 4 дБ. Слышал он ещё суше написанного: шина отзвука тише −70 LUFS
# мерилась как −70 (_quiet), и в его треке отзвук стоял на 3,9 дБ ниже тех −14; к тому,
# что он слышал, выходит +7,9 дБ.
#
# Эдлибы — «эй», «у», «йа» между строк — владелец 22.09.2026 сводил так: «по панировке
# раскидывал и эхо накидывал». Поэтому каждый выкрик встаёт в свою точку панорамы
# по кругу ADLIB_PANS — лево, право, ближе к центру слева и справа (_scatter), а у каждой
# дорожки эдлибов своё эхо в темп на ADLIB_ECHO дБ к ней: повторы приседают под
# ведущим и звучат в паузах, как броски саунд-дизайна. Полоса эдлибов уже, чем
# у ведущего, — 300 Гц … 5 кГц, как советует Rewak (Splice) отличать их от ведущего,
# и лёгкий перегруз (LaRay на эдлибах Cardi B — Sansamp): выкрик читается фоном,
# а не вторым ведущим.
PARTS = {
    "дабл": {"cut": 150, "gain": -8.0, "pan": 0.8, "deess": "deesser=i=0.8", "reverb": None},
    "бэк": {"cut": 200, "gain": -10.0, "pan": 0.9, "deess": DEESSER, "reverb": -10.0},
    "эдлиб": {"cut": 300, "gain": -6.0, "pan": 0.7, "deess": DEESSER, "reverb": -12.0,
              "color": "lowpass=f=5000,volume=6dB,asoftclip=type=atan:oversample=4,volume=-6dB"},
}
PARTS_ROOM = 1.2
ADLIB_PANS = (-0.7, 0.7, -0.4, 0.4)
ADLIB_PAUSE = 0.2
ADLIB_LONG = 2.0
ADLIB_ECHO = -8.0
# Выкрики одной дорожки записаны с разной силой, и громкость роли, одна на дорожку, часть
# из них топит, а часть ставит вровень с ведущим. Каждый выкрик подтягивается к медиане
# дорожки, но не дальше ADLIB_EVEN дБ: больше не даёт запас огибающей (_gain_track, +6 дБ),
# и шорох между выкриками не дорастает до выкрика. Уровень выкрика — там, где он звучит,
# в ADLIB_BODY дБ от своего верха: хвост в конце окна его не занижает. Событие тише медианы
# больше чем на ADLIB_FAINT дБ — вдох или шорох, а не выкрик, и не трогается вовсе: на той
# дорожке выкрики лежат от −5,5 до +3,1 дБ к медиане, а три события по 0,17–0,25 с —
# на 20–23 дБ тише, между ними пусто, порог — посередине.
ADLIB_EVEN = 6.0
ADLIB_BODY = 20.0
ADLIB_FAINT = 12.0
# Эдлибы присылают и под именем «бэк» (заказ 31c22c, 05.10.2026: 38 выкриков, медиана
# 0,44 с, вместе 22 с при 126 с голоса). Целиком «в стороны, −10 дБ» они шли от −13
# до −5 дБ к ведущему. Бэк, где кусок по медиане не длиннее BACK_SHOUT секунд, а все куски
# вместе короче BACK_SHARE от звучания ведущего, ведётся как эдлибы. Подпевка и дабл
# припева остаются бэком: строка припева — такт без паузы, от 1,2 с и при 160 ударах
# в минуту, поэтому мерка куска вдвое строже ADLIB_LONG; а короткие слоги, идущие плотно
# (четверть голоса и больше), — партия, а не выкрики между строк. Мерка выкриков одна,
# тот заказ; из настоящих бэков сверена одна шина ручного сведения (заказ a787f8: куски
# по 4 с, звучит всё время голоса) — сырых записей бэков под рукой не было.
BACK_SHOUT = 1.0
BACK_SHARE = 0.25


def _pan(position: float) -> str:
    """Моно — в точку панорамы от −1 (левый край) до 1 с постоянной мощностью."""
    angle = (position + 1) * math.pi / 4
    return f"pan=stereo|c0={math.cos(angle):.4f}*c0|c1={math.sin(angle):.4f}*c0"


def _scatter(events: list[tuple[float, float]], first: int = 0,
             lift: list[float] = ()) -> tuple[list[tuple[float, float]], list[tuple[float, float]]]:
    """Громкость левого и правого канала по ходу дорожки, точки (секунда, дБ) для _gain_track:
    выкрик events[i] — в точку ADLIB_PANS[first + i] с постоянной мощностью. Точка меняется
    посреди паузы перед выкриком, за 5 мс: в тишине не щёлкает. lift — поправка громкости
    каждому выкрику, дБ (_even), ставится в те же точки."""
    left, right = [], []
    for i, (start, _) in enumerate(events):
        angle, more = (ADLIB_PANS[(first + i) % len(ADLIB_PANS)] + 1) * math.pi / 4, lift[i] if lift else 0.0
        gains = (20 * math.log10(max(math.cos(angle), 1e-6)) + more, 20 * math.log10(max(math.sin(angle), 1e-6)) + more)
        at = 0.0
        if i:
            at = (events[i - 1][1] + start) / 2
            left.append((at, left[-1][1]))
            right.append((at, right[-1][1]))
            at += 0.005
        left.append((at, gains[0]))
        right.append((at, gains[1]))
    return left, right


def _even(heard: list[float], events: list[tuple[float, float]]) -> list[float]:
    """Поправка каждому выкрику, дБ: его уровень по огибающей heard (ADLIB_BODY) — к медиане
    дорожки, не дальше ADLIB_EVEN; шорох (ADLIB_FAINT) остаётся как был."""
    spans = [heard[round(a * ENV_RATE):round(b * ENV_RATE)] for a, b in events]
    loud = [10 * math.log10(statistics.fmean(10 ** (db / 10) for db in span if db > top - ADLIB_BODY))
            for span, top in zip(spans, map(max, spans))]
    middle = statistics.median(loud)
    return [0.0 if middle - db > ADLIB_FAINT else max(-ADLIB_EVEN, min(ADLIB_EVEN, middle - db)) for db in loud]


def _shouts(path: Path, lead: float) -> bool:
    """Дорожка — выкрики между строк, а не подпевка (BACK_SHOUT, BACK_SHARE); lead — сколько
    секунд звучит ведущий."""
    spans = [b - a for a, b in _lines(_envelope(path), VOICE_RANGE, ADLIB_PAUSE)]
    return len(spans) > 1 and statistics.median(spans) <= BACK_SHOUT and sum(spans) < BACK_SHARE * lead


def voices(parts: list[tuple[str, Path]], level: float, ride: Path | None, work: Path,
           tune: str = "", keep: bool = False, lead: float = 0.0) -> list[tuple[Path, float, str]]:
    """Части голоса сухими дорожками на своих местах: [(файл, поправка громкости в сумме, роль)].

    Цепочка — как у ведущего: срез, громкость к VOCAL_LUFS, компрессия, тембр по замеру,
    де-эссер своей роли; дальше — своя точка панорамы и своя громкость к ведущему level.
    tune — автотюн ведущего: ненастроенный дабл под настроенным голосом звучит фальшиво;
    keep — дорожки из одного проекта, тембр артиста не трогается (TONE); lead — сколько
    секунд звучит ведущий: бэк из коротких выкриков дальше идёт эдлибом (_shouts), и роль
    в ответе — та, какой он обработан; без lead бэк остаётся бэком."""
    if shouts := [path for part, path in parts if part == "бэк" and _shouts(path, lead)]:
        parts = [("эдлиб" if path in shouts else part, path) for part, path in parts]
        print("  бэк: короткие выкрики между строк — веду как эдлибы")
    placed = []
    for n, (part, path) in enumerate(parts):
        look, same = PARTS[part], [i for i, (other, _) in enumerate(parts) if other == part]
        chain = f"{FORMAT},{_center(path)}highpass=f={look['cut']},pan=mono|c0=0.5*c0+0.5*c1" + (f",{tune}" if tune else "")
        squeezed, dry = work / f"part{n}-comp.wav", work / f"part{n}.wav"
        _squeeze(path, f"{chain},volume={VOCAL_LUFS - loudness(path, chain + ',')[0]:.2f}dB", squeezed)
        tone = ("" if keep else _equalizer(squeezed, _lines(_envelope(squeezed)), work)) + look["deess"] \
            + (f",{look['color']}" if "color" in look else "")
        events = _lines(_envelope(squeezed), VOICE_RANGE, ADLIB_PAUSE) if part == "эдлиб" else []
        # Длинные партии под видом эдлибов (сплошной бэк) по кругу встали бы на минуту
        # в одну сторону — такие расходятся в стороны, как бэки.
        scattered = len(events) > 1 and statistics.median(b - a for a, b in events) <= ADLIB_LONG
        if scattered:
            # Уровень выкрика меряется после тембра и окраски: тембр по ходу сдвигает выкрики
            # по-разному, и поправка по огибающей до него оставляла прежний разброс.
            toned, seconds = work / f"part{n}-tone.wav", clips.probe_seconds(squeezed) + 1
            _ffmpeg("-i", squeezed, "-af", f"{tone},aformat=channel_layouts=mono", *reels.VOICE_CODEC, toned)
            left, right = (_gain_track(points, seconds, work / f"part{n}-{side}.wav")
                           for side, points in zip("lr", _scatter(events, 2 * same.index(n), _even(_envelope(toned), events))))
            _ffmpeg("-i", toned, "-i", left, "-i", right, "-filter_complex",
                    f"[0:a]pan=stereo|c0=c0|c1=c0[s];[1:a]aresample={RATE}[l];[2:a]aresample={RATE}[r];"
                    "[l][r]join=inputs=2:channel_layout=stereo[g];[s][g]amultiply,volume=2", *reels.VOICE_CODEC, dry)
        elif len(same) == 1 and part != "дабл":
            _ffmpeg("-i", squeezed, "-filter_complex", f"[0:a]{tone}[t];" + DOUBLE.replace("[0:a]", "[t]"),
                    "-map", "[w]", "-ar", RATE, *reels.VOICE_CODEC, dry)
        else:
            position = 0.0 if len(same) == 1 else look["pan"] * (1 if same.index(n) % 2 == 0 else -1)
            _ffmpeg("-i", squeezed, "-af", f"{tone},{_pan(position)}", *reels.VOICE_CODEC, dry)
        if part == "дабл" and ride:
            dry = _apply(dry, ride, work / f"part{n}-ride.wav")
        placed.append((dry, level + look["gain"] - loudness(dry)[0], part))
        where = (f"{len(events)} выкриков по панораме, каждый к одной громкости" if scattered
                 else "в стороны" if len(same) == 1 and part != "дабл" else "панорама")
        print(f"  {part}: {where}, {look['gain']:+.0f} дБ к ведущему")
    return placed


# ─────────────────────────── бот ───────────────────────────
#
# /svedenie или ссылка ?start=skleyka открывает заявку, дорожки приходят файлами —
# альбомом или по одной. Поллер у бота один (src/moderate.py), и считать сам он
# не может: пока идёт ffmpeg, бот не отвечал бы никому. Поэтому сведение — отдельный
# процесс (python -m src.skleyka --job ФАЙЛ): он сам качает дорожки, сводит
# и шлёт готовое, а дежурство на каждом круге (tick) смотрит, кончил ли он,
# и даёт ход следующей заявке. Сведение одно за раз: два разом делили бы машину
# и шли бы оба вдвое дольше.

# Инструкции почти нет: человек выбирает кнопкой, как пришлёт, а дальше бот сам
# спрашивает дорожки по одной — «шаг 1 из 2, пришли вокал». Роль дорожки — это вопрос,
# на который она пришла ответом, и называть файлы не нужно (владелец, 22.09.2026:
# «очень много текста, ни хрена не понятно и ни одной кнопки»). Стиль и ручки — после,
# под готовым треком.
ASK_MARK = "· пришли"
INTRO = ("🎛 <b>СВЕДЕНИЕ</b> — вокал и бит в готовый трек. Бесплатно, автоматом, за несколько минут.\n\n"
         "✏️ В сведении разбираться не нужно — пиши мне обычными словами, как другу: «голос входит на дропе», "
         "«хочу погрязнее», «как у Travis Scott». Напишешь заранее — учту сразу, после — пересоберу.\n\n"
         "Как пришлёшь?")
PICK = "Отметь, что у тебя есть отдельно, — потом попрошу каждую дорожку по очереди."
